CREATE OR REPLACE FUNCTION public.admin_archive_driver(p_driver_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;
begin
    perform public.higo_assert_admin('manage_drivers', true);
    if coalesce(trim(p_reason),'')='' then raise exception 'archive_reason_required'; end if;
    select to_jsonb(p) into v_before from public.profiles p where id=p_driver_id and role='driver' for update;
    if v_before is null then raise exception 'driver_not_found'; end if;
    update public.profiles set archived_at=now(), archived_by=auth.uid(), archive_reason=trim(p_reason), status='offline', subscription_status='suspended' where id=p_driver_id;
    insert into public.admin_audit_log(actor_id, action, entity_type, entity_id, before_data, after_data, reason)
    select auth.uid(),'driver.archive','profile',p_driver_id::text,v_before,to_jsonb(p),trim(p_reason) from public.profiles p where p.id=p_driver_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_archive_promo(p_id bigint, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;
begin
    perform public.higo_assert_admin('manage_promos', true);
    if public.higo_admin_role() <> 'super_admin' then raise exception 'super_admin_required'; end if;
    if coalesce(trim(p_reason),'')='' then raise exception 'archive_reason_required'; end if;
    select to_jsonb(p) into v_before from public.promo_codes p where id=p_id for update;
    if v_before is null then raise exception 'promo_not_found'; end if;
    update public.promo_codes set active=false, archived_at=now(), archived_by=auth.uid() where id=p_id;
    insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,before_data,after_data,reason)
    select auth.uid(),'promo.archive','promo_code',p_id::text,v_before,to_jsonb(p),trim(p_reason) from public.promo_codes p where p.id=p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_archive_zone(p_id bigint, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before jsonb;
begin
    perform public.higo_assert_admin('manage_zones', true);
    if coalesce(trim(p_reason), '') = '' then
        raise exception 'archive_reason_required';
    end if;

    select to_jsonb(z) into v_before
    from public.coverage_zones z
    where z.id = p_id
    for update;

    if v_before is null then
        raise exception 'zone_not_found';
    end if;

    update public.coverage_zones
    set active = false
    where id = p_id;

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id, before_data, after_data, reason
    )
    select auth.uid(), 'zone.archive', 'coverage_zones', p_id::text,
           v_before, to_jsonb(z), trim(p_reason)
    from public.coverage_zones z
    where z.id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_business_analytics(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_days integer := greatest(7, least(coalesce(p_days, 30), 365));
    v_since timestamptz;
    v_revenue numeric := 0;
    v_payers bigint := 0;
    v_payments bigint := 0;
    v_renewing bigint := 0;
    v_membership_daily jsonb := '[]'::jsonb;
    v_trip_daily jsonb := '[]'::jsonb;
begin
    v_since :=
        date_trunc('day', now())
        - (v_days - 1) * interval '1 day';

    perform public.higo_assert_admin('view_analytics');

    select
        coalesce(sum(amount), 0),
        count(*),
        count(distinct driver_id)
    into
        v_revenue,
        v_payments,
        v_payers
    from public.driver_memberships
    where voided_at is null
      and paid_at >= v_since;

    select count(*)
    into v_renewing
    from (
        select driver_id
        from public.driver_memberships
        where voided_at is null
          and paid_at >= v_since
        group by driver_id
        having count(*) > 1
    ) as renewing_drivers;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'day', gs.bucket_day::date,
                'revenue', coalesce(md.revenue, 0),
                'payments', coalesce(md.payments, 0)
            )
            order by gs.bucket_day
        ),
        '[]'::jsonb
    )
    into v_membership_daily
    from generate_series(
        v_since,
        date_trunc('day', now()),
        interval '1 day'
    ) as gs(bucket_day)
    left join (
        select
            date_trunc('day', paid_at) as bucket_day,
            sum(amount) as revenue,
            count(*) as payments
        from public.driver_memberships
        where voided_at is null
          and paid_at >= v_since
        group by date_trunc('day', paid_at)
    ) as md
        on md.bucket_day = gs.bucket_day;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'day', gs.bucket_day::date,
                'volume', coalesce(td.volume, 0),
                'rides', coalesce(td.rides, 0)
            )
            order by gs.bucket_day
        ),
        '[]'::jsonb
    )
    into v_trip_daily
    from generate_series(
        v_since,
        date_trunc('day', now()),
        interval '1 day'
    ) as gs(bucket_day)
    left join (
        select
            date_trunc('day', created_at) as bucket_day,
            sum(
                case
                    when payment_confirmed_at is not null then price
                    else 0
                end
            ) as volume,
            count(*) as rides
        from public.rides
        where created_at >= v_since
        group by date_trunc('day', created_at)
    ) as td
        on td.bucket_day = gs.bucket_day;

    return jsonb_build_object(
        'days', v_days,
        'membershipRevenue', v_revenue,
        'payments', v_payments,
        'payingDrivers', v_payers,
        'averageRevenuePerDriver',
            case
                when v_payers > 0
                    then round(v_revenue / v_payers, 2)
                else 0
            end,
        'renewalRate',
            case
                when v_payers > 0
                    then round(
                        (v_renewing::numeric / v_payers::numeric) * 100,
                        1
                    )
                else 0
            end,
        'activeMemberships',
            (
                select count(*)
                from public.admin_driver_membership_status
                where membership_state in (
                    'active',
                    'expiring_soon',
                    'grace_period'
                )
            ),
        'tripVolume',
            coalesce(
                (
                    select sum(price)
                    from public.rides
                    where created_at >= v_since
                      and payment_confirmed_at is not null
                ),
                0
            ),
        'rides',
            (
                select count(*)
                from public.rides
                where created_at >= v_since
            ),
        'membershipDaily', v_membership_daily,
        'tripDaily', v_trip_daily,
        'generatedAt', now()
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_change_profile_role(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;
begin
    perform public.higo_assert_admin('manage_users', true);
    if public.higo_admin_role()<>'super_admin' then raise exception 'super_admin_required'; end if;
    if p_role not in ('passenger','user','driver','admin','merchant') then raise exception 'invalid_profile_role'; end if;
    if p_user_id=auth.uid() and p_role<>'admin' then raise exception 'cannot_demote_self'; end if;
    select to_jsonb(p) into v_before from public.profiles p where id=p_user_id for update;
    update public.profiles set role=p_role where id=p_user_id;
    if p_role='admin' then
        insert into public.admin_staff_roles(user_id,staff_role) values(p_user_id,'viewer') on conflict(user_id) do nothing;
    end if;
    insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,before_data,after_data)
    select auth.uid(),'profile.role_change','profile',p_user_id::text,v_before,to_jsonb(p) from public.profiles p where p.id=p_user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_claim_driver_application_conversion(p_application_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_application public.driver_applications%rowtype;
    v_claim_id uuid := gen_random_uuid();
begin
    perform public.higo_assert_admin('manage_drivers', true);

    select * into v_application
      from public.driver_applications
     where application_code = upper(trim(p_application_code))
     for update;

    if not found then
        raise exception 'driver_application_not_found' using errcode = 'P0002';
    end if;

    if v_application.status = 'converted' or v_application.converted_user_id is not null then
        return to_jsonb(v_application) || jsonb_build_object('already_converted', true);
    end if;
    if v_application.status <> 'approved' then
        raise exception 'application_not_approved' using errcode = '22023';
    end if;
    if v_application.conversion_claimed_at is not null
       and v_application.conversion_claimed_at >= now() - interval '15 minutes' then
        raise exception 'conversion_in_progress' using errcode = '55000';
    end if;

    update public.driver_applications
       set conversion_claim_id = v_claim_id,
           conversion_claimed_at = now(),
           conversion_claimed_by = auth.uid()
     where id = v_application.id
     returning * into v_application;

    return to_jsonb(v_application) || jsonb_build_object(
        'conversion_claim_id', v_claim_id,
        'already_converted', false
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_complete_driver_application_conversion(p_application_code text, p_claim_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before public.driver_applications%rowtype;
    v_after public.driver_applications%rowtype;
begin
    perform public.higo_assert_admin('manage_drivers', true);

    select * into v_before
      from public.driver_applications
     where application_code = upper(trim(p_application_code))
     for update;

    if not found then
        raise exception 'driver_application_not_found' using errcode = 'P0002';
    end if;
    if v_before.status = 'converted' and v_before.converted_user_id = p_user_id then
        return to_jsonb(v_before);
    end if;
    if v_before.status <> 'approved'
       or v_before.conversion_claim_id is distinct from p_claim_id
       or v_before.conversion_claimed_by is distinct from auth.uid()
       or v_before.conversion_claimed_at < now() - interval '15 minutes' then
        raise exception 'invalid_conversion_claim' using errcode = '55000';
    end if;

    update public.driver_applications
       set status = 'converted',
           converted_user_id = p_user_id,
           converted_at = now(),
           last_status_changed_at = now(),
           last_status_changed_by = auth.uid(),
           conversion_claim_id = null,
           conversion_claimed_at = null,
           conversion_claimed_by = null
     where id = v_before.id
     returning * into v_after;

    insert into public.driver_application_events(
        application_id, actor_type, actor_id, event_type, from_status, to_status, metadata
    ) values (
        v_before.id, 'admin', auth.uid(), 'driver_account_created',
        v_before.status, v_after.status, jsonb_build_object('user_id', p_user_id)
    );

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id, before_data, after_data, reason, metadata
    ) values (
        auth.uid(), 'driver_application.convert', 'driver_application', v_before.application_code,
        jsonb_build_object('status', v_before.status),
        jsonb_build_object('status', v_after.status, 'user_id', p_user_id),
        'Solicitud aprobada convertida a cuenta Higo Driver',
        jsonb_build_object('source', 'admin_driver_applications')
    );

    return to_jsonb(v_after);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_dashboard_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_today timestamptz := date_trunc('day', now());
    v_month timestamptz := date_trunc('month', now());
    v_result jsonb;
begin
    perform public.higo_assert_admin('view_dashboard');
    select jsonb_build_object(
        'membershipRevenueToday', coalesce((select sum(amount) from public.driver_memberships where voided_at is null and paid_at >= v_today), 0),
        'membershipRevenueMonth', coalesce((select sum(amount) from public.driver_memberships where voided_at is null and paid_at >= v_month), 0),
        'activeMemberships', (select count(*) from public.admin_driver_membership_status where membership_state in ('active','expiring_soon','grace_period')),
        'expiredMemberships', (select count(*) from public.admin_driver_membership_status where membership_state in ('expired','no_membership')),
        'expiringSoon', (select count(*) from public.admin_driver_membership_status where membership_state = 'expiring_soon'),
        'driversOnline', (select count(*) from public.profiles where role='driver' and status='online' and updated_at > now() - interval '90 seconds'),
        'ridesToday', (select count(*) from public.rides where created_at >= v_today),
        'tripVolumeToday', coalesce((select sum(price) from public.rides where created_at >= v_today and payment_confirmed_at is not null), 0),
        'openDisputes', (select count(*) from public.rides where payment_confirmed_at is null and (payment_reference is not null or payment_confirmed_by_user or payment_confirmed_by_driver)),
        'supportUnread', coalesce((select count(*) from public.support_threads where status='open' and unread_for_admin), 0),
        'activeWithoutMembership', (select count(*) from public.admin_driver_membership_status where subscription_status='active' and membership_state in ('expired','no_membership','suspended','archived')),
        'subsidyCostMonth', 0,
        'generatedAt', now()
    ) into v_result;
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_fair_dispatch_metrics(p_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_hours integer := greatest(1, least(coalesce(p_hours, 24), 720));
    v_result jsonb;
begin
    perform public.higo_assert_admin('view_analytics', true);

    with recent_dispatches as (
        select d.*
        from public.ride_dispatches d
        where d.started_at >= now() - make_interval(hours => v_hours)
    ),
    acceptance as (
        select
            count(*) as dispatches,
            count(*) filter (where d.status in ('accepted','completed')) as accepted,
            avg(extract(epoch from (coalesce(r.accepted_at, d.completed_at) - d.started_at)))
                filter (where d.status in ('accepted','completed')) as avg_accept_seconds,
            percentile_cont(0.9) within group (
                order by extract(epoch from (coalesce(r.accepted_at, d.completed_at) - d.started_at))
            ) filter (where d.status in ('accepted','completed')) as p90_accept_seconds,
            avg(d.offers_created) as avg_offers
        from recent_dispatches d
        join public.rides r on r.id = d.ride_id
    ),
    waves as (
        select coalesce(jsonb_object_agg(wave_number::text, accepted_count), '{}'::jsonb) as data
        from (
            select o.wave_number, count(*) as accepted_count
            from public.ride_offers o
            join recent_dispatches d on d.ride_id = o.ride_id
            where o.status = 'accepted'
            group by o.wave_number
        ) grouped
    ),
    fairness as (
        select
            count(*) as drivers_offered,
            min(driver_offer_count) as min_offers_per_driver,
            max(driver_offer_count) as max_offers_per_driver,
            avg(driver_offer_count) as avg_offers_per_driver
        from (
            select o.driver_id, count(*)::numeric as driver_offer_count
            from public.ride_offers o
            where o.offered_at >= now() - make_interval(hours => v_hours)
            group by o.driver_id
        ) per_driver
    )
    select jsonb_build_object(
        'windowHours', v_hours,
        'dispatches', coalesce(a.dispatches, 0),
        'accepted', coalesce(a.accepted, 0),
        'acceptRate', case when coalesce(a.dispatches, 0) = 0 then 0
            else round(a.accepted::numeric / a.dispatches::numeric, 4) end,
        'avgAcceptSeconds', round(coalesce(a.avg_accept_seconds, 0)::numeric, 2),
        'p90AcceptSeconds', round(coalesce(a.p90_accept_seconds, 0)::numeric, 2),
        'avgOffersPerDispatch', round(coalesce(a.avg_offers, 0)::numeric, 2),
        'acceptedByWave', w.data,
        'driversOffered', coalesce(f.drivers_offered, 0),
        'minOffersPerDriver', coalesce(f.min_offers_per_driver, 0),
        'maxOffersPerDriver', coalesce(f.max_offers_per_driver, 0),
        'avgOffersPerDriver', round(coalesce(f.avg_offers_per_driver, 0)::numeric, 2)
    ) into v_result
    from acceptance a cross join waves w cross join fairness f;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_role text;
    v_require_mfa boolean;
    v_session_minutes integer;
begin
    if not public.higo_is_admin() then
        return jsonb_build_object('authorized', false);
    end if;
    v_role := public.higo_admin_role();
    select require_mfa, session_minutes into v_require_mfa, v_session_minutes
      from public.admin_security_settings where singleton;
    return jsonb_build_object(
        'authorized', true,
        'user_id', auth.uid(),
        'staff_role', v_role,
        'require_mfa', coalesce(v_require_mfa, false),
        'session_minutes', coalesce(v_session_minutes, 60),
        'aal', coalesce(auth.jwt()->>'aal', 'aal1'),
        'permissions', jsonb_build_object(
            'view_dashboard', public.higo_admin_can('view_dashboard'),
            'view_analytics', public.higo_admin_can('view_analytics'),
            'view_users', public.higo_admin_can('view_users'),
            'manage_memberships', public.higo_admin_can('manage_memberships'),
            'manage_drivers', public.higo_admin_can('manage_drivers'),
            'manage_support', public.higo_admin_can('manage_support'),
            'manage_operations', public.higo_admin_can('manage_operations'),
            'manage_pricing', public.higo_admin_can('manage_pricing'),
            'manage_zones', public.higo_admin_can('manage_zones'),
            'manage_disputes', public.higo_admin_can('manage_disputes'),
            'manage_users', v_role = 'super_admin',
            'manage_security', v_role = 'super_admin',
            'manage_promos', v_role = 'super_admin',
            'manage_shop', v_role = 'super_admin'
        )
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_driver_application(p_application_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_application public.driver_applications%rowtype;
    v_documents jsonb;
    v_events jsonb;
begin
    perform public.higo_assert_admin('manage_drivers');

    select * into v_application
    from public.driver_applications
    where application_code = upper(trim(p_application_code));

    if not found then
        return null;
    end if;

    select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at), '[]'::jsonb)
      into v_documents
      from public.driver_application_documents d
     where d.application_id = v_application.id;

    select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc), '[]'::jsonb)
      into v_events
      from (
          select * from public.driver_application_events
          where application_id = v_application.id
          order by created_at desc
          limit 100
      ) e;

    return to_jsonb(v_application)
        || jsonb_build_object('documents', v_documents, 'events', v_events);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_fraud_signals_v2()
 RETURNS TABLE(subject_type text, subject_id text, signal text, severity text, metadata jsonb, computed_at timestamp with time zone, subject_name text, subject_phone text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('manage_operations');

    return query
    select
        f.subject_type::text,
        f.subject_id::text,
        f.signal::text,
        f.severity::text,
        f.metadata,
        f.computed_at,
        p.full_name,
        p.phone
    from public.fraud_signals f
    left join public.profiles p
      on f.subject_type in ('passenger', 'driver')
     and p.id::text = f.subject_id::text
    order by
        case f.severity
            when 'high' then 1
            when 'medium' then 2
            else 3
        end,
        f.computed_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_get_ride_detail(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result jsonb;
begin
    perform public.higo_assert_admin('manage_operations');

    select jsonb_build_object(
        'ride', to_jsonb(r),
        'passenger', jsonb_strip_nulls(jsonb_build_object(
            'id', passenger.id,
            'full_name', passenger.full_name,
            'email', passenger.email,
            'phone', coalesce(r.passenger_phone, passenger.phone),
            'avatar_url', passenger.avatar_url,
            'status', passenger.status,
            'created_at', passenger.created_at
        )),
        'driver', jsonb_strip_nulls(jsonb_build_object(
            'id', driver.id,
            'full_name', driver.full_name,
            'email', driver.email,
            'phone', driver.phone,
            'avatar_url', driver.avatar_url,
            'status', driver.status,
            'vehicle_type', driver.vehicle_type,
            'vehicle_brand', driver.vehicle_brand,
            'vehicle_model', driver.vehicle_model,
            'vehicle_color', driver.vehicle_color,
            'license_plate', driver.license_plate,
            'last_location_update', driver.last_location_update,
            'suspended_at', driver.suspended_at,
            'subscription_status', driver.subscription_status
        )),
        'route', jsonb_build_object(
            'pickup', r.pickup,
            'dropoff', r.dropoff,
            'pickupLat', r.pickup_lat,
            'pickupLng', r.pickup_lng,
            'dropoffLat', r.dropoff_lat,
            'dropoffLng', r.dropoff_lng,
            'stops', coalesce(r.stops, '[]'::jsonb),
            'quotedDistanceKm', r.quoted_distance_km
        ),
        'timeline', jsonb_build_object(
            'createdAt', r.created_at,
            'acceptedAt', r.accepted_at,
            'arrivedPickupAt', r.arrived_at_pickup_at,
            'startedAt', r.started_at,
            'arrivedDropoffAt', r.arrived_at_dropoff_at,
            'completedAt', r.completed_at,
            'cancelledAt', r.cancelled_at,
            'updatedAt', coalesce(
                r.completed_at,
                r.cancelled_at,
                r.arrived_at_dropoff_at,
                r.started_at,
                r.arrived_at_pickup_at,
                r.accepted_at,
                r.created_at
            )
        ),
        'pricing', jsonb_build_object(
            'price', r.price,
            'priceBeforeDiscount', r.price_before_discount,
            'discountAmount', r.discount_amount,
            'waitSeconds', r.wait_seconds,
            'waitFee', r.wait_fee,
            'promoCodeId', r.promo_code_id,
            'snapshot', r.pricing_snapshot,
            'pricingVersion', r.pricing_version,
            'pricingModel', r.pricing_model,
            'multiplier', r.pricing_multiplier,
            'multiplierReason', r.pricing_multiplier_reason,
            'baseAmount', r.pricing_base_amount,
            'distanceAmount', r.pricing_distance_amount,
            'timeAmount', r.pricing_time_amount,
            'stopsAmount', r.pricing_stops_amount,
            'extrasAmount', r.pricing_extras_amount,
            'minimumFare', r.pricing_minimum_fare
        ),
        'payment', jsonb_build_object(
            'method', r.payment_method,
            'reference', r.payment_reference,
            'confirmedByPassenger', r.payment_confirmed_by_user,
            'confirmedByDriver', r.payment_confirmed_by_driver,
            'confirmedAt', r.payment_confirmed_at,
            'hasDispute', r.payment_confirmed_at is null and (
                r.payment_reference is not null
                or coalesce(r.payment_confirmed_by_user, false)
                or coalesce(r.payment_confirmed_by_driver, false)
            )
        ),
        'promo', case when promo.id is null then null else to_jsonb(promo) end,
        'dispatch', coalesce((
            select to_jsonb(rd) from public.ride_dispatches rd where rd.ride_id = r.id
        ), '{}'::jsonb),
        'offers', coalesce((
            select jsonb_agg(
                to_jsonb(o) || jsonb_build_object(
                    'driverName', op.full_name,
                    'driverPhone', op.phone,
                    'licensePlate', op.license_plate,
                    'vehicleModel', op.vehicle_model
                ) order by o.offered_at, o.rank_position nulls last, o.id
            )
            from public.ride_offers o
            left join public.profiles op on op.id = o.driver_id
            where o.ride_id = r.id
        ), '[]'::jsonb),
        'events', coalesce((
            select jsonb_agg(
                to_jsonb(e) || jsonb_build_object('actorName', actor.full_name)
                order by e.created_at, e.id
            )
            from public.ride_state_events e
            left join public.profiles actor on actor.id = e.actor_id
            where e.ride_id = r.id
        ), '[]'::jsonb),
        'supportThreads', coalesce((
            select jsonb_agg(
                to_jsonb(st)
                order by coalesce(
                    to_jsonb(st)->>'updated_at',
                    to_jsonb(st)->>'last_message_at',
                    to_jsonb(st)->>'created_at'
                ) desc nulls last
            )
            from public.support_threads st
            where st.user_id = r.user_id or st.user_id = r.driver_id
        ), '[]'::jsonb),
        'fraudSignals', coalesce((
            select jsonb_agg(
                to_jsonb(fs)
                order by coalesce(
                    to_jsonb(fs)->>'computed_at',
                    to_jsonb(fs)->>'updated_at',
                    to_jsonb(fs)->>'created_at'
                ) desc nulls last
            )
            from public.fraud_signals fs
            where fs.subject_type = 'ride' and fs.subject_id = r.id::text
        ), '[]'::jsonb),
        'auditLog', coalesce((
            select jsonb_agg(to_jsonb(al) order by al.created_at desc)
            from (
                select * from public.admin_audit_log
                where entity_type in ('ride','rides') and entity_id = r.id::text
                order by created_at desc
                limit 50
            ) al
        ), '[]'::jsonb),
        'termsAcceptances', coalesce((
            select jsonb_agg(to_jsonb(ta) order by ta.accepted_at desc)
            from public.terms_acceptances ta
            where ta.ride_id = r.id
        ), '[]'::jsonb),
        'metrics', jsonb_build_object(
            'assignmentSeconds', extract(epoch from (r.accepted_at - r.created_at))::integer,
            'pickupWaitSeconds', extract(epoch from (r.started_at - r.arrived_at_pickup_at))::integer,
            'tripSeconds', extract(epoch from (r.completed_at - r.started_at))::integer,
            'totalLifecycleSeconds', extract(epoch from (
                coalesce(r.completed_at, r.cancelled_at, now()) - r.created_at
            ))::integer
        )
    )
    into v_result
    from public.rides r
    left join public.profiles passenger on passenger.id = r.user_id
    left join public.profiles driver on driver.id = r.driver_id
    left join public.promo_codes promo on promo.id = r.promo_code_id
    where r.id = p_ride_id
      and coalesce(r.service_type, 'ride') <> 'delivery';

    if v_result is null then
        raise exception 'ride_not_found' using errcode = 'P0002';
    end if;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_driver_applications(p_query text DEFAULT NULL::text, p_status text DEFAULT 'all'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(application_code text, full_name text, email text, phone text, city text, vehicle_type text, vehicle_brand text, vehicle_model text, license_plate text, status text, documents_count bigint, pending_documents_count bigint, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('manage_drivers');
    return query
    select
        a.application_code,
        a.full_name,
        a.email,
        a.phone,
        a.city,
        a.vehicle_type,
        a.vehicle_brand,
        a.vehicle_model,
        a.license_plate,
        a.status,
        count(d.id) as documents_count,
        count(d.id) filter (where d.review_status = 'pending') as pending_documents_count,
        a.created_at,
        a.updated_at
    from public.driver_applications a
    left join public.driver_application_documents d on d.application_id = a.id
    where (coalesce(p_status, 'all') = 'all' or a.status = p_status)
      and (
        coalesce(trim(p_query), '') = ''
        or a.application_code ilike '%' || trim(p_query) || '%'
        or a.full_name ilike '%' || trim(p_query) || '%'
        or a.email ilike '%' || trim(p_query) || '%'
        or a.phone ilike '%' || trim(p_query) || '%'
        or a.license_plate ilike '%' || trim(p_query) || '%'
      )
    group by a.id
    order by a.created_at desc
    limit greatest(1, least(coalesce(p_limit, 50), 100))
    offset greatest(coalesce(p_offset, 0), 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_rides(p_status_bucket text DEFAULT 'active'::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_query text DEFAULT NULL::text, p_vehicle_type text DEFAULT NULL::text, p_has_promo boolean DEFAULT NULL::boolean, p_has_incident boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
    v_items jsonb := '[]'::jsonb;
    v_has_more boolean := false;
    v_next_created_at timestamptz;
    v_next_id bigint;
begin
    perform public.higo_assert_admin('manage_operations');

    with candidates as (
        select
            r.id as ride_id,
            r.created_at,
            to_jsonb(r) as ride,
            jsonb_strip_nulls(jsonb_build_object(
                'id', passenger.id,
                'full_name', passenger.full_name,
                'email', passenger.email,
                'phone', coalesce(r.passenger_phone, passenger.phone),
                'avatar_url', passenger.avatar_url,
                'status', passenger.status,
                'created_at', passenger.created_at
            )) as passenger,
            jsonb_strip_nulls(jsonb_build_object(
                'id', driver.id,
                'full_name', driver.full_name,
                'email', driver.email,
                'phone', driver.phone,
                'avatar_url', driver.avatar_url,
                'status', driver.status,
                'vehicle_type', driver.vehicle_type,
                'vehicle_brand', driver.vehicle_brand,
                'vehicle_model', driver.vehicle_model,
                'vehicle_color', driver.vehicle_color,
                'license_plate', driver.license_plate,
                'suspended_at', driver.suspended_at
            )) as driver,
            jsonb_build_object(
                'total', coalesce(offers.total, 0),
                'offered', coalesce(offers.offered, 0),
                'accepted', coalesce(offers.accepted, 0),
                'expired', coalesce(offers.expired, 0),
                'withdrawn', coalesce(offers.withdrawn, 0),
                'maxWave', coalesce(offers.max_wave, 0),
                'firstOfferAt', offers.first_offer_at,
                'acceptedAt', offers.accepted_at,
                'acceptedDistanceKm', offers.accepted_distance_km
            ) as offer_summary,
            coalesce(to_jsonb(dispatch_row), '{}'::jsonb) as dispatch,
            coalesce(support.open_count, 0) as open_support_count,
            coalesce(fraud.signal_count, 0) as fraud_signal_count,
            (
                r.payment_confirmed_at is null
                and (
                    r.payment_reference is not null
                    or coalesce(r.payment_confirmed_by_user, false)
                    or coalesce(r.payment_confirmed_by_driver, false)
                )
            ) as has_payment_dispute,
            (
                coalesce(fraud.signal_count, 0) > 0
                or (
                    r.payment_confirmed_at is null
                    and (
                        r.payment_reference is not null
                        or coalesce(r.payment_confirmed_by_user, false)
                        or coalesce(r.payment_confirmed_by_driver, false)
                    )
                )
            ) as has_incident,
            extract(epoch from (
                coalesce(r.accepted_at, offers.accepted_at) - r.created_at
            ))::integer as assignment_seconds,
            extract(epoch from (
                coalesce(r.completed_at, r.cancelled_at, now())
                - coalesce(r.started_at, r.accepted_at, r.created_at)
            ))::integer as lifecycle_seconds
        from public.rides r
        left join public.profiles passenger on passenger.id = r.user_id
        left join public.profiles driver on driver.id = r.driver_id
        left join public.ride_dispatches dispatch_row on dispatch_row.ride_id = r.id
        left join lateral (
            select
                count(*)::integer as total,
                count(*) filter (where o.status = 'offered')::integer as offered,
                count(*) filter (where o.status = 'accepted')::integer as accepted,
                count(*) filter (where o.status = 'expired')::integer as expired,
                count(*) filter (where o.status = 'withdrawn')::integer as withdrawn,
                max(o.wave_number)::integer as max_wave,
                min(o.offered_at) as first_offer_at,
                max(o.responded_at) filter (where o.status = 'accepted') as accepted_at,
                max(o.distance_km) filter (where o.status = 'accepted') as accepted_distance_km
            from public.ride_offers o
            where o.ride_id = r.id
        ) offers on true
        left join lateral (
            select count(*) filter (where st.status = 'open')::integer as open_count
            from public.support_threads st
            where st.user_id = r.user_id or st.user_id = r.driver_id
        ) support on true
        left join lateral (
            select count(*)::integer as signal_count
            from public.fraud_signals fs
            where fs.subject_type = 'ride'
              and fs.subject_id = r.id::text
        ) fraud on true
        where coalesce(r.service_type, 'ride') <> 'delivery'
          and (p_date_from is null or r.created_at >= p_date_from)
          and (p_date_to is null or r.created_at < p_date_to)
          and (
              coalesce(trim(p_status_bucket), 'active') = 'all'
              or (p_status_bucket = 'active' and r.status in ('requested','accepted','in_progress','arrived_at_dropoff'))
              or (p_status_bucket = 'completed' and r.status = 'completed')
              or (p_status_bucket = 'cancelled' and r.status = 'cancelled')
              or (p_status_bucket not in ('active','completed','cancelled','all') and r.status = p_status_bucket)
          )
          and (
              coalesce(trim(p_vehicle_type), '') = ''
              or public.higo_canonical_vehicle_type(r.ride_type)
                    = public.higo_canonical_vehicle_type(p_vehicle_type)
          )
          and (
              p_has_promo is null
              or p_has_promo = (r.promo_code_id is not null)
          )
          and (
              p_has_incident is null
              or p_has_incident = (
                  coalesce(fraud.signal_count, 0) > 0
                  or (
                      r.payment_confirmed_at is null
                      and (
                          r.payment_reference is not null
                          or coalesce(r.payment_confirmed_by_user, false)
                          or coalesce(r.payment_confirmed_by_driver, false)
                      )
                  )
              )
          )
          and (
              coalesce(trim(p_query), '') = ''
              or r.id::text = trim(p_query)
              or r.pickup ilike '%' || trim(p_query) || '%'
              or r.dropoff ilike '%' || trim(p_query) || '%'
              or coalesce(r.passenger_phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(r.payment_reference, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.full_name, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.email, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.full_name, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.email, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.license_plate, '') ilike '%' || trim(p_query) || '%'
          )
          and (
              p_cursor_created_at is null
              or r.created_at < p_cursor_created_at
              or (r.created_at = p_cursor_created_at and r.id < coalesce(p_cursor_id, 9223372036854775807))
          )
        order by r.created_at desc, r.id desc
        limit v_limit + 1
    ),
    page as (
        select * from candidates
        order by created_at desc, ride_id desc
        limit v_limit
    )
    select coalesce(jsonb_agg(
        p.ride || jsonb_build_object(
            'passenger', p.passenger,
            'driver', p.driver,
            'offerSummary', p.offer_summary,
            'dispatch', p.dispatch,
            'openSupportCount', p.open_support_count,
            'fraudSignalCount', p.fraud_signal_count,
            'hasPaymentDispute', p.has_payment_dispute,
            'hasIncident', p.has_incident,
            'assignmentSeconds', p.assignment_seconds,
            'lifecycleSeconds', p.lifecycle_seconds
        ) order by p.created_at desc, p.ride_id desc
    ), '[]'::jsonb)
    into v_items
    from page p;

    with candidates as (
        select r.id, r.created_at
        from public.rides r
        left join public.profiles passenger on passenger.id = r.user_id
        left join public.profiles driver on driver.id = r.driver_id
        left join lateral (
            select count(*)::integer as signal_count
            from public.fraud_signals fs
            where fs.subject_type = 'ride' and fs.subject_id = r.id::text
        ) fraud on true
        where coalesce(r.service_type, 'ride') <> 'delivery'
          and (p_date_from is null or r.created_at >= p_date_from)
          and (p_date_to is null or r.created_at < p_date_to)
          and (
              coalesce(trim(p_status_bucket), 'active') = 'all'
              or (p_status_bucket = 'active' and r.status in ('requested','accepted','in_progress','arrived_at_dropoff'))
              or (p_status_bucket = 'completed' and r.status = 'completed')
              or (p_status_bucket = 'cancelled' and r.status = 'cancelled')
              or (p_status_bucket not in ('active','completed','cancelled','all') and r.status = p_status_bucket)
          )
          and (coalesce(trim(p_vehicle_type), '') = '' or public.higo_canonical_vehicle_type(r.ride_type) = public.higo_canonical_vehicle_type(p_vehicle_type))
          and (p_has_promo is null or p_has_promo = (r.promo_code_id is not null))
          and (p_has_incident is null or p_has_incident = (coalesce(fraud.signal_count, 0) > 0 or (r.payment_confirmed_at is null and (r.payment_reference is not null or coalesce(r.payment_confirmed_by_user, false) or coalesce(r.payment_confirmed_by_driver, false)))))
          and (
              coalesce(trim(p_query), '') = ''
              or r.id::text = trim(p_query)
              or r.pickup ilike '%' || trim(p_query) || '%'
              or r.dropoff ilike '%' || trim(p_query) || '%'
              or coalesce(r.passenger_phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(r.payment_reference, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.full_name, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.email, '') ilike '%' || trim(p_query) || '%'
              or coalesce(passenger.phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.full_name, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.email, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.phone, '') ilike '%' || trim(p_query) || '%'
              or coalesce(driver.license_plate, '') ilike '%' || trim(p_query) || '%'
          )
          and (
              p_cursor_created_at is null
              or r.created_at < p_cursor_created_at
              or (r.created_at = p_cursor_created_at and r.id < coalesce(p_cursor_id, 9223372036854775807))
          )
        order by r.created_at desc, r.id desc
        limit v_limit + 1
    )
    select count(*) > v_limit into v_has_more from candidates;

    if v_has_more and jsonb_array_length(v_items) > 0 then
        select
            (item->>'created_at')::timestamptz,
            (item->>'id')::bigint
        into v_next_created_at, v_next_id
        from jsonb_array_elements(v_items) with ordinality entries(item, ord)
        order by ord desc
        limit 1;
    end if;

    return jsonb_build_object(
        'items', v_items,
        'hasMore', v_has_more,
        'nextCursor', case when v_has_more then jsonb_build_object(
            'createdAt', v_next_created_at,
            'id', v_next_id
        ) else null end,
        'generatedAt', now()
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_list_staff()
 RETURNS TABLE(user_id uuid, full_name text, phone text, staff_role text, active boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('view_users');
    return query
    select p.id, p.full_name, p.phone, coalesce(r.staff_role,'viewer'), coalesce(r.active,true), r.updated_at
    from public.profiles p left join public.admin_staff_roles r on r.user_id=p.id
    where p.role='admin' order by p.full_name nulls last;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_override_ride_status(p_ride_id bigint, p_target_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before public.rides%rowtype;
    v_after jsonb;
    v_target text := lower(trim(coalesce(p_target_status, '')));
begin
    perform public.higo_assert_admin('manage_operations', true);

    if v_target not in ('completed','cancelled') then
        raise exception 'invalid_admin_ride_target_status';
    end if;
    if coalesce(trim(p_reason), '') = '' then
        raise exception 'admin_ride_reason_required';
    end if;

    select * into v_before
    from public.rides r
    where r.id = p_ride_id
      and coalesce(r.service_type, 'ride') <> 'delivery'
    for update;

    if not found then raise exception 'ride_not_found'; end if;
    if v_before.status in ('completed','cancelled') then
        if v_before.status = v_target then return to_jsonb(v_before); end if;
        raise exception 'terminal_ride_cannot_be_overridden';
    end if;
    if v_target = 'completed' and v_before.status not in ('accepted','in_progress','arrived_at_dropoff') then
        raise exception 'ride_not_ready_for_completion';
    end if;

    update public.rides r
    set status = v_target,
        completed_at = case when v_target = 'completed' then coalesce(r.completed_at, now()) else r.completed_at end,
        cancelled_at = case when v_target = 'cancelled' then coalesce(r.cancelled_at, now()) else r.cancelled_at end,
        cancellation_reason = case when v_target = 'cancelled' then trim(p_reason) else r.cancellation_reason end,
        updated_at = now()
    where r.id = p_ride_id
    returning to_jsonb(r) into v_after;

    perform public.higo_log_ride_event(
        p_ride_id,
        v_before.status,
        v_target,
        'admin.override',
        jsonb_build_object('reason', trim(p_reason), 'actorRole', public.higo_admin_role())
    );

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id, before_data, after_data, reason, metadata
    ) values (
        auth.uid(),
        'ride.override_' || v_target,
        'ride',
        p_ride_id::text,
        to_jsonb(v_before),
        v_after,
        trim(p_reason),
        jsonb_build_object('source', 'admin_rides')
    );

    return v_after;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_platform_funnel(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_days integer := greatest(1, least(coalesce(p_days, 30), 365));
    v_since timestamptz;
begin
    perform public.higo_assert_admin('view_analytics');
    v_since := now() - make_interval(days => v_days);

    return jsonb_build_object(
        'days', v_days,
        'rideRequestStarted', (
            select count(*)
            from public.platform_events
            where event_name = 'ride.request_started'
              and created_at >= v_since
        ),
        'rideRequested', (
            select count(*)
            from public.rides
            where created_at >= v_since
        ),
        'rideAccepted', (
            select count(*)
            from public.rides
            where accepted_at is not null
              and created_at >= v_since
        ),
        'rideCompleted', (
            select count(*)
            from public.rides
            where status = 'completed'
              and created_at >= v_since
        ),
        'rideCancelled', (
            select count(*)
            from public.rides
            where status = 'cancelled'
              and created_at >= v_since
        ),
        'membershipCheckoutViewed', (
            select count(*)
            from public.platform_events
            where event_name = 'membership.checkout_viewed'
              and created_at >= v_since
        ),
        'membershipPaymentValidated', (
            select count(*)
            from public.driver_memberships
            where voided_at is null
              and paid_at >= v_since
        ),
        'medianAcceptSeconds', (
            select percentile_cont(0.5) within group (
                order by extract(epoch from (r.accepted_at - r.created_at))
            )
            from public.rides r
            where r.accepted_at is not null
              and r.created_at >= v_since
        ),
        'p90AcceptSeconds', (
            select percentile_cont(0.9) within group (
                order by extract(epoch from (r.accepted_at - r.created_at))
            )
            from public.rides r
            where r.accepted_at is not null
              and r.created_at >= v_since
        ),
        'unassignedOlderThan10Minutes', (
            select count(*)
            from public.rides r
            where r.status = 'requested'
              and r.created_at < now() - interval '10 minutes'
        ),
        'generatedAt', now()
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_record_driver_membership(p_driver_id uuid, p_plan_id uuid, p_payment_method text, p_payment_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_plan public.driver_membership_plans%rowtype;
    v_id bigint;
    v_start timestamptz := now();
    v_expires timestamptz;
begin
    perform public.higo_assert_admin('manage_memberships', true);
    select * into v_plan from public.driver_membership_plans where id=p_plan_id and active;
    if not found then raise exception 'membership_plan_not_found'; end if;
    if not exists(select 1 from public.profiles where id=p_driver_id and role='driver' and archived_at is null) then
        raise exception 'driver_not_found_or_archived';
    end if;
    v_expires := v_start + make_interval(days => v_plan.duration_days);
    insert into public.driver_memberships(
        driver_id, plan_id, plan, amount, currency, period, paid_at, expires_at,
        status, payment_method, payment_reference, notes, created_by
    ) values (
        p_driver_id, v_plan.id, v_plan.code, coalesce(p_amount, v_plan.amount), v_plan.currency,
        v_plan.period, v_start, v_expires, 'active', nullif(trim(p_payment_method),''),
        nullif(trim(p_payment_reference),''), nullif(trim(p_notes),''), auth.uid()
    ) returning id into v_id;
    perform public.higo_sync_driver_membership(p_driver_id);
    insert into public.admin_audit_log(actor_id, action, entity_type, entity_id, after_data)
    values(auth.uid(),'membership.record','driver_membership',v_id::text,
        jsonb_build_object('driver_id',p_driver_id,'plan_id',p_plan_id,'amount',coalesce(p_amount,v_plan.amount),'expires_at',v_expires));
    return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_refund_ride(p_ride_id bigint, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id     UUID;
    v_movement_id BIGINT;
BEGIN
    IF NOT public.is_admin(auth.uid()) THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'amount_must_be_positive' USING ERRCODE = '22023';
    END IF;
    SELECT user_id INTO v_user_id FROM public.rides WHERE id = p_ride_id;
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'ride_not_found' USING ERRCODE = '02000';
    END IF;

    INSERT INTO public.wallet_movements (
        user_id, type, amount, ref_ride_id, note, created_by
    ) VALUES (
        v_user_id, 'refund_credit', p_amount, p_ride_id, p_note, auth.uid()
    )
    RETURNING id INTO v_movement_id;

    RETURN v_movement_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_release_driver_application_conversion(p_application_code text, p_claim_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_count integer;
begin
    perform public.higo_assert_admin('manage_drivers', true);

    update public.driver_applications
       set conversion_claim_id = null,
           conversion_claimed_at = null,
           conversion_claimed_by = null
     where application_code = upper(trim(p_application_code))
       and conversion_claim_id = p_claim_id
       and status = 'approved';
    get diagnostics v_count = row_count;
    return v_count = 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_review_driver_application_document(p_document_id uuid, p_review_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before public.driver_application_documents%rowtype;
    v_after public.driver_application_documents%rowtype;
begin
    perform public.higo_assert_admin('manage_drivers', true);
    if p_review_status not in ('approved','rejected') then
        raise exception 'invalid_document_review_status' using errcode = '22023';
    end if;

    select * into v_before
      from public.driver_application_documents
     where id = p_document_id
     for update;
    if not found then
        raise exception 'driver_application_document_not_found' using errcode = 'P0002';
    end if;

    update public.driver_application_documents
       set review_status = p_review_status,
           review_notes = nullif(trim(coalesce(p_notes, '')), ''),
           reviewed_by = auth.uid(),
           reviewed_at = now()
     where id = p_document_id
     returning * into v_after;

    insert into public.driver_application_events(
        application_id, actor_type, actor_id, event_type, metadata
    ) values (
        v_before.application_id, 'admin', auth.uid(), 'document_reviewed',
        jsonb_build_object(
            'document_id', v_before.id,
            'document_type', v_before.document_type,
            'review_status', p_review_status,
            'notes', p_notes
        )
    );

    return to_jsonb(v_after);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_ride_operations_metrics(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result jsonb;
begin
    perform public.higo_assert_admin('manage_operations');

    with base as (
        select r.*
        from public.rides r
        where coalesce(r.service_type, 'ride') <> 'delivery'
          and (p_date_from is null or r.created_at >= p_date_from)
          and (p_date_to is null or r.created_at < p_date_to)
    ), metrics as (
        select
            count(*)::integer as total,
            count(*) filter (where status in ('requested','accepted','in_progress','arrived_at_dropoff'))::integer as active,
            count(*) filter (where status = 'completed')::integer as completed,
            count(*) filter (where status = 'cancelled')::integer as cancelled,
            count(distinct user_id)::integer as unique_passengers,
            count(distinct driver_id) filter (where driver_id is not null)::integer as unique_drivers,
            coalesce(sum(price) filter (where status = 'completed'), 0) as transacted_volume,
            coalesce(avg(price) filter (where status = 'completed'), 0) as average_price,
            avg(extract(epoch from (accepted_at - created_at))) filter (where accepted_at is not null) as avg_assignment_seconds,
            avg(extract(epoch from (completed_at - started_at))) filter (where completed_at is not null and started_at is not null) as avg_trip_seconds,
            count(*) filter (
                where payment_confirmed_at is null
                  and (payment_reference is not null or coalesce(payment_confirmed_by_user, false) or coalesce(payment_confirmed_by_driver, false))
            )::integer as payment_disputes,
            count(*) filter (where promo_code_id is not null)::integer as promo_rides,
            count(*) filter (where pricing_version = 4)::integer as pricing_v4_rides
        from base
    ), fraud as (
        select count(distinct fs.subject_id)::integer as ride_count
        from public.fraud_signals fs
        join base b on b.id::text = fs.subject_id
        where fs.subject_type = 'ride'
    )
    select jsonb_build_object(
        'total', m.total,
        'active', m.active,
        'completed', m.completed,
        'cancelled', m.cancelled,
        'completionRate', case when m.total = 0 then 0 else round(m.completed::numeric / m.total::numeric, 4) end,
        'uniquePassengers', m.unique_passengers,
        'uniqueDrivers', m.unique_drivers,
        'transactedVolume', round(m.transacted_volume, 2),
        'averagePrice', round(m.average_price, 2),
        'avgAssignmentSeconds', round(coalesce(m.avg_assignment_seconds, 0)::numeric, 2),
        'avgTripSeconds', round(coalesce(m.avg_trip_seconds, 0)::numeric, 2),
        'paymentDisputes', m.payment_disputes,
        'fraudSignals', coalesce(f.ride_count, 0),
        'promoRides', m.promo_rides,
        'pricingV4Rides', m.pricing_v4_rides,
        'generatedAt', now()
    ) into v_result
    from metrics m cross join fraud f;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_save_promo(p_id bigint, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id bigint;
    v_source text := coalesce(p_payload->>'funding_source','higo');
    v_budget numeric := nullif(p_payload->>'budget_amount','')::numeric;
    v_before jsonb;
begin
    perform public.higo_assert_admin('manage_promos', true);
    if public.higo_admin_role() <> 'super_admin' then raise exception 'super_admin_required'; end if;
    if coalesce(trim(p_payload->>'code'),'')='' then raise exception 'promo_code_required'; end if;
    if v_source not in ('higo','sponsor','driver_campaign') then raise exception 'invalid_funding_source'; end if;
    if v_budget is null or v_budget <= 0 then raise exception 'promo_budget_required'; end if;
    if v_source='sponsor' and coalesce(trim(p_payload->>'sponsor_name'),'')='' then raise exception 'sponsor_name_required'; end if;

    if p_id is null then
        insert into public.promo_codes(
            code, description, discount_type, discount_value, max_uses, max_uses_per_user,
            min_ride_amount, expires_at, active, funding_source, sponsor_name, budget_amount
        ) values (
            upper(trim(p_payload->>'code')), nullif(trim(p_payload->>'description'),''),
            coalesce(p_payload->>'discount_type','percent'), coalesce((p_payload->>'discount_value')::numeric,0),
            nullif(p_payload->>'max_uses','')::integer, coalesce((p_payload->>'max_uses_per_user')::integer,1),
            coalesce((p_payload->>'min_ride_amount')::numeric,0), nullif(p_payload->>'expires_at','')::timestamptz,
            coalesce((p_payload->>'active')::boolean,true), v_source, nullif(trim(p_payload->>'sponsor_name'),''), v_budget
        ) returning id into v_id;
        insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,after_data)
        select auth.uid(),'promo.create','promo_code',v_id::text,to_jsonb(p) from public.promo_codes p where p.id=v_id;
    else
        select to_jsonb(p) into v_before from public.promo_codes p where id=p_id for update;
        if v_before is null then raise exception 'promo_not_found'; end if;
        update public.promo_codes set
            description=nullif(trim(p_payload->>'description'),''),
            discount_type=coalesce(p_payload->>'discount_type',discount_type),
            discount_value=coalesce((p_payload->>'discount_value')::numeric,discount_value),
            max_uses=nullif(p_payload->>'max_uses','')::integer,
            max_uses_per_user=coalesce((p_payload->>'max_uses_per_user')::integer,1),
            min_ride_amount=coalesce((p_payload->>'min_ride_amount')::numeric,0),
            expires_at=nullif(p_payload->>'expires_at','')::timestamptz,
            active=coalesce((p_payload->>'active')::boolean,active),
            funding_source=v_source,
            sponsor_name=nullif(trim(p_payload->>'sponsor_name'),''),
            budget_amount=v_budget
        where id=p_id returning id into v_id;
        insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,before_data,after_data)
        select auth.uid(),'promo.update','promo_code',v_id::text,v_before,to_jsonb(p) from public.promo_codes p where p.id=v_id;
    end if;
    return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_driver_application_status(p_application_code text, p_status text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before public.driver_applications%rowtype;
    v_after public.driver_applications%rowtype;
    v_required_approved integer := 0;
    v_required_unapproved integer := 0;
begin
    perform public.higo_assert_admin('manage_drivers', true);

    select * into v_before
      from public.driver_applications
     where application_code = upper(trim(p_application_code))
     for update;

    if not found then
        raise exception 'driver_application_not_found' using errcode = 'P0002';
    end if;

    if not public.higo_driver_application_transition_allowed(v_before.status, p_status) then
        raise exception 'invalid_driver_application_transition:%->%', v_before.status, p_status
            using errcode = '22023';
    end if;

    if p_status = 'approved' and v_before.status <> 'approved' then
        select
            count(*) filter (where review_status = 'approved'),
            count(*) filter (where review_status <> 'approved')
          into v_required_approved, v_required_unapproved
          from (
              select distinct on (document_type)
                     document_type, review_status
                from public.driver_application_documents
               where application_id = v_before.id
                 and document_type in (
                     'profile_photo','identity','driver_license',
                     'vehicle_registration','rcv','vehicle_photo'
                 )
               order by document_type, created_at desc
          ) latest_required;

        if v_required_approved <> 6 or v_required_unapproved <> 0 then
            raise exception 'required_documents_not_approved' using errcode = '22023';
        end if;
    end if;

    if p_status in ('correction_requested','waitlist','rejected')
       and nullif(trim(coalesce(p_reason, '')), '') is null then
        raise exception 'status_reason_required' using errcode = '22023';
    end if;

    update public.driver_applications
       set status = p_status,
           status_reason = nullif(trim(coalesce(p_reason, '')), ''),
           last_status_changed_at = now(),
           last_status_changed_by = auth.uid()
     where id = v_before.id
     returning * into v_after;

    insert into public.driver_application_events(
        application_id, actor_type, actor_id, event_type, from_status, to_status, metadata
    ) values (
        v_before.id, 'admin', auth.uid(), 'status_changed', v_before.status, v_after.status,
        coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('reason', p_reason)
    );

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id, before_data, after_data, reason, metadata
    ) values (
        auth.uid(), 'driver_application.status_change', 'driver_application', v_before.application_code,
        jsonb_build_object('status', v_before.status),
        jsonb_build_object('status', v_after.status),
        p_reason,
        coalesce(p_metadata, '{}'::jsonb)
    );

    return to_jsonb(v_after);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_driver_exception(p_driver_id uuid, p_action text, p_reason text, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before jsonb;
begin
    perform public.higo_assert_admin('manage_drivers', true);
    if coalesce(trim(p_reason),'')='' then raise exception 'reason_required'; end if;
    select to_jsonb(p) into v_before from public.profiles p where id=p_driver_id and role='driver' for update;
    if v_before is null then raise exception 'driver_not_found'; end if;
    if p_action='suspend' then
        update public.profiles set subscription_status='suspended', suspended_at=now(), suspension_reason=trim(p_reason) where id=p_driver_id;
    elsif p_action='grace' then
        if p_until is null or p_until <= now() then raise exception 'future_until_required'; end if;
        update public.profiles set subscription_override_until=p_until, suspended_at=null, suspension_reason=null where id=p_driver_id;
    elsif p_action='clear' then
        update public.profiles set subscription_override_until=null, suspended_at=null, suspension_reason=null where id=p_driver_id;
        perform public.higo_sync_driver_membership(p_driver_id);
    else
        raise exception 'invalid_driver_action';
    end if;
    insert into public.admin_audit_log(actor_id, action, entity_type, entity_id, before_data, after_data, reason)
    select auth.uid(),'driver.'||p_action,'profile',p_driver_id::text,v_before,to_jsonb(p),trim(p_reason)
      from public.profiles p where p.id=p_driver_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_fair_dispatch_flags(p_progressive_enabled boolean, p_shadow_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before jsonb;
    v_after jsonb;
begin
    perform public.higo_assert_admin('manage_operations', true);

    select to_jsonb(f) into v_before
    from public.platform_runtime_flags f
    where singleton
    for update;

    update public.platform_runtime_flags
    set fair_progressive_dispatch = coalesce(p_progressive_enabled, false),
        fair_dispatch_shadow = coalesce(p_shadow_enabled, false),
        updated_at = now(),
        updated_by = auth.uid()
    where singleton
    returning to_jsonb(platform_runtime_flags.*) into v_after;

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id,
        before_data, after_data, reason
    ) values (
        auth.uid(),
        'platform.fair_dispatch_flags',
        'platform_runtime_flags',
        'singleton',
        v_before,
        v_after,
        'Cambio explícito del rollout de despacho equitativo.'
    );

    return v_after;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_platform_runtime_flags(p_directed_ride_offers boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before jsonb;
    v_after jsonb;
begin
    perform public.higo_assert_admin('manage_operations', true);

    select to_jsonb(f) into v_before
    from public.platform_runtime_flags f
    where singleton
    for update;

    update public.platform_runtime_flags
    set directed_ride_offers = coalesce(p_directed_ride_offers, false),
        updated_at = now(),
        updated_by = auth.uid()
    where singleton
    returning to_jsonb(platform_runtime_flags.*) into v_after;

    insert into public.admin_audit_log(
        actor_id, action, entity_type, entity_id,
        before_data, after_data, reason
    ) values (
        auth.uid(),
        'platform.runtime_flags',
        'platform_runtime_flags',
        'singleton',
        v_before,
        v_after,
        'Cambio explícito de banderas operativas.'
    );

    return v_after;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_security_settings(p_require_mfa boolean, p_session_minutes integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('manage_users', true);
    if public.higo_admin_role()<>'super_admin' then raise exception 'super_admin_required'; end if;
    update public.admin_security_settings
       set require_mfa=p_require_mfa,
           session_minutes=greatest(15,least(coalesce(p_session_minutes,60),720)),
           updated_at=now(), updated_by=auth.uid()
     where singleton;
    insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,after_data)
    values(auth.uid(),'admin.security_settings','admin_security_settings','singleton',jsonb_build_object('require_mfa',p_require_mfa,'session_minutes',p_session_minutes));
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_pricing_rollout(p_mode text, p_pilot_percentage numeric DEFAULT 0, p_maximum_multiplier numeric DEFAULT 1.30, p_notes text DEFAULT NULL::text)
 RETURNS pricing_rollout_config
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result public.pricing_rollout_config%rowtype;
begin
    if not public.higo_is_admin() then
        raise exception 'admin_required' using errcode = '42501';
    end if;
    if p_mode not in ('legacy','shadow','pilot','active') then
        raise exception 'invalid_pricing_rollout_mode';
    end if;
    if p_pilot_percentage < 0 or p_pilot_percentage > 100 then
        raise exception 'invalid_pilot_percentage';
    end if;
    if p_maximum_multiplier < 1 or p_maximum_multiplier > 3 then
        raise exception 'invalid_maximum_multiplier';
    end if;

    update public.pricing_rollout_config
    set mode = p_mode,
        pilot_percentage = p_pilot_percentage,
        maximum_multiplier = p_maximum_multiplier,
        notes = nullif(trim(p_notes), ''),
        updated_by = auth.uid(),
        updated_at = now()
    where id = 1
    returning * into v_result;

    if to_regclass('public.admin_audit_log') is not null then
        insert into public.admin_audit_log(
            actor_id, action, entity_type, entity_id, after_data, metadata
        ) values (
            auth.uid(),
            'pricing.rollout_updated',
            'pricing_rollout_config',
            '1',
            to_jsonb(v_result),
            jsonb_build_object('source', 'admin_pricing')
        );
    end if;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_staff_role(p_user_id uuid, p_staff_role text, p_active boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('manage_users', true);
    if public.higo_admin_role() <> 'super_admin' then raise exception 'super_admin_required'; end if;
    if p_staff_role not in ('super_admin','operations','support','finance','viewer') then raise exception 'invalid_staff_role'; end if;
    if p_user_id=auth.uid() and (p_staff_role<>'super_admin' or not p_active) then raise exception 'cannot_demote_self'; end if;
    insert into public.admin_staff_roles(user_id,staff_role,active,updated_by)
    values(p_user_id,p_staff_role,p_active,auth.uid())
    on conflict(user_id) do update set staff_role=excluded.staff_role, active=excluded.active, updated_at=now(), updated_by=auth.uid();
    insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,after_data)
    values(auth.uid(),'admin.staff_role','admin_staff_role',p_user_id::text,jsonb_build_object('staff_role',p_staff_role,'active',p_active));
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_void_driver_membership(p_membership_id bigint, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_driver uuid;
    v_before jsonb;
begin
    perform public.higo_assert_admin('manage_memberships', true);
    if coalesce(trim(p_reason),'') = '' then raise exception 'void_reason_required'; end if;
    select driver_id, to_jsonb(dm) into v_driver, v_before
      from public.driver_memberships dm where id=p_membership_id and voided_at is null for update;
    if v_driver is null then raise exception 'membership_not_found'; end if;
    update public.driver_memberships
       set status='voided', voided_at=now(), voided_by=auth.uid(), void_reason=trim(p_reason), updated_at=now()
     where id=p_membership_id;
    perform public.higo_sync_driver_membership(v_driver);
    insert into public.admin_audit_log(actor_id, action, entity_type, entity_id, before_data, reason)
    values(auth.uid(),'membership.void','driver_membership',p_membership_id::text,v_before,trim(p_reason));
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_promo_code(p_code text, p_ride_id bigint, p_user_id uuid, p_ride_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_promo public.promo_codes%ROWTYPE; v_uses_by_user INTEGER; v_discount NUMERIC; v_final NUMERIC;
BEGIN
    SELECT * INTO v_promo FROM public.promo_codes WHERE code = UPPER(p_code) AND active = TRUE;
    IF NOT FOUND THEN RETURN jsonb_build_object('valid', FALSE, 'message', 'Código inválido o inactivo'); END IF;
    IF v_promo.expires_at IS NOT NULL AND v_promo.expires_at < NOW() THEN RETURN jsonb_build_object('valid', FALSE, 'message', 'El código ha expirado'); END IF;
    IF v_promo.max_uses IS NOT NULL AND v_promo.used_count >= v_promo.max_uses THEN RETURN jsonb_build_object('valid', FALSE, 'message', 'El código alcanzó su límite de usos'); END IF;
    SELECT COUNT(*) INTO v_uses_by_user FROM public.ride_promos WHERE user_id = p_user_id AND promo_code = v_promo.code;
    IF v_uses_by_user >= COALESCE(v_promo.max_uses_per_user, 1) THEN RETURN jsonb_build_object('valid', FALSE, 'message', 'Ya usaste este código antes'); END IF;
    IF p_ride_amount < COALESCE(v_promo.min_ride_amount, 0) THEN RETURN jsonb_build_object('valid', FALSE, 'message', format('El viaje debe ser de al menos $%s', v_promo.min_ride_amount)); END IF;
    IF v_promo.discount_type = 'percent' THEN v_discount := ROUND(p_ride_amount * v_promo.discount_value / 100.0, 2);
    ELSE v_discount := LEAST(v_promo.discount_value, p_ride_amount); END IF;
    v_final := GREATEST(p_ride_amount - v_discount, 0);
    INSERT INTO public.ride_promos (ride_id, user_id, promo_code, discount_amount) VALUES (p_ride_id, p_user_id, v_promo.code, v_discount);
    UPDATE public.promo_codes SET used_count = used_count + 1 WHERE id = v_promo.id;
    RETURN jsonb_build_object('valid', TRUE, 'discount_amount', v_discount, 'final_price', v_final, 'message', format('Descuento aplicado: $%s', v_discount));
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_promo_code(p_code text, p_ride_id uuid, p_user_id uuid, p_ride_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_promo public.promo_codes%ROWTYPE;
    v_uses_by_user INTEGER;
    v_discount NUMERIC;
    v_final NUMERIC;
BEGIN
    -- Buscar el código activo
    SELECT * INTO v_promo
      FROM public.promo_codes
     WHERE code = UPPER(p_code) AND active = TRUE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('valid', FALSE, 'message', 'Código inválido o inactivo');
    END IF;

    -- Vencimiento
    IF v_promo.expires_at IS NOT NULL AND v_promo.expires_at < NOW() THEN
        RETURN jsonb_build_object('valid', FALSE, 'message', 'El código ha expirado');
    END IF;

    -- Cupo máximo global
    IF v_promo.max_uses IS NOT NULL AND v_promo.used_count >= v_promo.max_uses THEN
        RETURN jsonb_build_object('valid', FALSE, 'message', 'El código alcanzó su límite de usos');
    END IF;

    -- Cupo por usuario
    SELECT COUNT(*) INTO v_uses_by_user
      FROM public.ride_promos
     WHERE user_id = p_user_id AND promo_code = v_promo.code;
    IF v_uses_by_user >= COALESCE(v_promo.max_uses_per_user, 1) THEN
        RETURN jsonb_build_object('valid', FALSE, 'message', 'Ya usaste este código antes');
    END IF;

    -- Monto mínimo
    IF p_ride_amount < COALESCE(v_promo.min_ride_amount, 0) THEN
        RETURN jsonb_build_object('valid', FALSE,
            'message', format('El viaje debe ser de al menos $%s', v_promo.min_ride_amount));
    END IF;

    -- Calcular descuento
    IF v_promo.discount_type = 'percent' THEN
        v_discount := ROUND(p_ride_amount * v_promo.discount_value / 100.0, 2);
    ELSE
        v_discount := LEAST(v_promo.discount_value, p_ride_amount);
    END IF;
    v_final := GREATEST(p_ride_amount - v_discount, 0);

    -- Insertar uso (UNIQUE en ride_id evita doble aplicación)
    INSERT INTO public.ride_promos (ride_id, user_id, promo_code, discount_amount)
    VALUES (p_ride_id, p_user_id, v_promo.code, v_discount);

    -- Incrementar contador global
    UPDATE public.promo_codes SET used_count = used_count + 1 WHERE id = v_promo.id;

    RETURN jsonb_build_object(
        'valid', TRUE,
        'discount_amount', v_discount,
        'final_price', v_final,
        'message', format('Descuento aplicado: $%s', v_discount)
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.assign_referral_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_code TEXT;
    v_attempts INT := 0;
BEGIN
    IF NEW.referral_code IS NOT NULL THEN
        RETURN NEW;
    END IF;
    LOOP
        v_code := public.gen_referral_code();
        EXIT WHEN NOT EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = v_code);
        v_attempts := v_attempts + 1;
        EXIT WHEN v_attempts > 10;
    END LOOP;
    NEW.referral_code := v_code;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_delivery_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.service_type = 'delivery'
     AND NEW.status = 'completed'
     AND OLD.status <> 'completed' THEN
    INSERT INTO public.delivery_receipts (ride_id, total_amount, cod_amount, currency)
    VALUES (NEW.id, NEW.price, NEW.cod_amount, COALESCE(NEW.cod_currency, 'USD'))
    ON CONFLICT (ride_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_ride_request_v2(p_client_request_id uuid, p_pickup text, p_dropoff text, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_stops jsonb DEFAULT '[]'::jsonb, p_promo_code text DEFAULT NULL::text, p_passenger_phone text DEFAULT NULL::text, p_delivery_info jsonb DEFAULT NULL::jsonb, p_payer text DEFAULT NULL::text, p_cod_amount numeric DEFAULT NULL::numeric, p_terms_version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_role text;
    v_quote jsonb;
    v_ride_id bigint;
    v_existing jsonb;
    v_promo_id bigint;
    v_promo record;
    v_discount numeric := 0;
    v_stops_count integer := 0;
    v_coverage boolean := true;
begin
    if v_user_id is null then
        raise exception 'authentication_required' using errcode = '42501';
    end if;
    if p_client_request_id is null then
        raise exception 'client_request_id_required';
    end if;

    select p.role into v_role
    from public.profiles p
    where p.id = v_user_id;
    if coalesce(v_role, 'passenger') not in ('passenger', 'user') then
        raise exception 'passenger_role_required' using errcode = '42501';
    end if;

    select jsonb_build_object(
        'rideId', r.id,
        'price', r.price,
        'status', r.status,
        'idempotentReplay', true
    )
    into v_existing
    from public.rides r
    where r.user_id = v_user_id
      and r.client_request_id = p_client_request_id;
    if v_existing is not null then
        return v_existing;
    end if;

    begin
        execute 'select public.is_within_coverage($1,$2)'
        into v_coverage
        using p_pickup_lat, p_pickup_lng;
    exception
        when undefined_function then v_coverage := true;
        when others then v_coverage := true;
    end;
    if not coalesce(v_coverage, false) then
        raise exception 'pickup_outside_coverage';
    end if;

    if jsonb_typeof(coalesce(p_stops, '[]'::jsonb)) = 'array' then
        v_stops_count := jsonb_array_length(coalesce(p_stops, '[]'::jsonb));
    end if;

    -- Lock the promo row before quoting so max-use and budget checks remain
    -- valid until redemption is recorded in this transaction.
    if coalesce(trim(p_promo_code), '') <> '' then
        select * into v_promo
        from public.promo_codes pc
        where upper(pc.code) = upper(trim(p_promo_code))
        for update;
    end if;

    v_quote := public.higo_quote_ride_v2(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        v_stops_count,
        p_promo_code,
        v_user_id
    );

    if coalesce(trim(p_promo_code), '') <> ''
       and not coalesce((v_quote->>'promoValid')::boolean, false) then
        raise exception 'promo_invalid:%', coalesce(v_quote->>'promoError', 'unknown');
    end if;

    v_promo_id := nullif(v_quote->>'promoId', '')::bigint;
    v_discount := coalesce((v_quote->>'discount')::numeric, 0);

    insert into public.rides(
        user_id,
        pickup,
        dropoff,
        price,
        ride_type,
        status,
        payment_method,
        passenger_phone,
        pickup_lat,
        pickup_lng,
        dropoff_lat,
        dropoff_lng,
        service_type,
        delivery_info,
        payer,
        cod_amount,
        cod_currency,
        client_request_id,
        quoted_distance_km,
        price_before_discount,
        discount_amount,
        pricing_snapshot,
        promo_code_id,
        stops
    ) values (
        v_user_id,
        trim(p_pickup),
        trim(p_dropoff),
        (v_quote->>'finalPrice')::numeric,
        public.higo_canonical_vehicle_type(p_vehicle_type),
        'requested',
        'direct',
        nullif(trim(p_passenger_phone), ''),
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        coalesce(nullif(trim(p_service_type), ''), 'ride'),
        p_delivery_info,
        p_payer,
        p_cod_amount,
        case when coalesce(p_cod_amount, 0) > 0 then 'USD' else null end,
        p_client_request_id,
        (v_quote->>'distanceKm')::numeric,
        (v_quote->>'subtotal')::numeric,
        v_discount,
        v_quote,
        v_promo_id,
        coalesce(p_stops, '[]'::jsonb)
    )
    returning id into v_ride_id;

    if v_promo_id is not null then
        insert into public.promo_redemptions(
            promo_id, ride_id, user_id, discount_amount
        ) values (
            v_promo_id, v_ride_id, v_user_id, v_discount
        );

        update public.promo_codes
        set used_count = coalesce(used_count, 0) + 1,
            spent_amount = coalesce(spent_amount, 0) + v_discount
        where id = v_promo_id;
    end if;

    if coalesce(p_service_type, 'ride') = 'delivery'
       and coalesce(trim(p_terms_version), '') <> ''
       and to_regclass('public.terms_acceptances') is not null then
        insert into public.terms_acceptances(
            user_id, terms_kind, terms_version, accepted_at, ride_id
        ) values (
            v_user_id, 'delivery', trim(p_terms_version), now(), v_ride_id
        );
    end if;

    return jsonb_build_object(
        'rideId', v_ride_id,
        'price', (v_quote->>'finalPrice')::numeric,
        'quote', v_quote,
        'status', 'requested',
        'idempotentReplay', false
    );
exception
    when unique_violation then
        select jsonb_build_object(
            'rideId', r.id,
            'price', r.price,
            'status', r.status,
            'idempotentReplay', true
        )
        into v_existing
        from public.rides r
        where r.user_id = v_user_id
          and r.client_request_id = p_client_request_id;
        if v_existing is not null then
            return v_existing;
        end if;
        raise;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_ride_request_v3(p_client_request_id uuid, p_pickup text, p_dropoff text, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_stops jsonb DEFAULT '[]'::jsonb, p_promo_code text DEFAULT NULL::text, p_passenger_phone text DEFAULT NULL::text, p_delivery_info jsonb DEFAULT NULL::jsonb, p_payer text DEFAULT NULL::text, p_cod_amount numeric DEFAULT NULL::numeric, p_terms_version text DEFAULT NULL::text, p_client_price_floor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_created jsonb;
    v_ride_id bigint;
    v_result jsonb;
    v_floor numeric := greatest(0, coalesce(p_client_price_floor, 0));
begin
    v_created := public.create_ride_request_v2(
        p_client_request_id,
        p_pickup,
        p_dropoff,
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        p_stops,
        p_promo_code,
        p_passenger_phone,
        p_delivery_info,
        p_payer,
        p_cod_amount,
        p_terms_version
    );

    v_ride_id := nullif(v_created->>'rideId', '')::bigint;
    if v_ride_id is null then
        raise exception 'ride_creation_failed';
    end if;

    if v_floor > 0 then
        update public.rides r
        set price = greatest(coalesce(r.price, 0), v_floor),
            price_before_discount = greatest(
                coalesce(r.price_before_discount, 0),
                v_floor + coalesce(r.discount_amount, 0)
            ),
            pricing_snapshot = coalesce(r.pricing_snapshot, '{}'::jsonb)
                || jsonb_build_object(
                    'clientPriceFloor', v_floor,
                    'clientPriceFloorApplied', v_floor > coalesce((r.pricing_snapshot->>'finalPrice')::numeric, 0)
                )
        where r.id = v_ride_id
          and r.user_id = auth.uid();
    end if;

    select jsonb_build_object(
        'rideId', r.id,
        'price', r.price,
        'status', r.status,
        'quote', r.pricing_snapshot,
        'idempotentReplay', coalesce((v_created->>'idempotentReplay')::boolean, false)
    )
    into v_result
    from public.rides r
    where r.id = v_ride_id
      and r.user_id = auth.uid();

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_ride_request_v4(p_client_request_id uuid, p_pickup text, p_dropoff text, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_stops jsonb DEFAULT '[]'::jsonb, p_promo_code text DEFAULT NULL::text, p_passenger_phone text DEFAULT NULL::text, p_delivery_info jsonb DEFAULT NULL::jsonb, p_payer text DEFAULT NULL::text, p_cod_amount numeric DEFAULT NULL::numeric, p_terms_version text DEFAULT NULL::text, p_client_subtotal_floor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_created jsonb;
    v_ride public.rides%rowtype;
    v_floor numeric := greatest(0, coalesce(p_client_subtotal_floor, 0));
    v_subtotal numeric;
    v_old_discount numeric;
    v_new_discount numeric;
    v_discount_delta numeric;
    v_promo public.promo_codes%rowtype;
    v_result jsonb;
begin
    v_created := public.create_ride_request_v2(
        p_client_request_id,
        p_pickup,
        p_dropoff,
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        p_stops,
        p_promo_code,
        p_passenger_phone,
        p_delivery_info,
        p_payer,
        p_cod_amount,
        p_terms_version
    );

    select * into v_ride
    from public.rides r
    where r.id = (v_created->>'rideId')::bigint
      and r.user_id = auth.uid()
    for update;

    if not found then
        raise exception 'ride_creation_failed';
    end if;

    v_subtotal := greatest(coalesce(v_ride.price_before_discount, v_ride.price, 0), v_floor);
    v_old_discount := coalesce(v_ride.discount_amount, 0);
    v_new_discount := v_old_discount;

    if v_ride.promo_code_id is not null then
        select * into v_promo
        from public.promo_codes pc
        where pc.id = v_ride.promo_code_id
        for update;

        v_new_discount := case
            when v_promo.discount_type = 'percent'
                then v_subtotal * coalesce(v_promo.discount_value, 0) / 100
            else least(coalesce(v_promo.discount_value, 0), v_subtotal)
        end;
        v_new_discount := round(greatest(0, least(v_new_discount, v_subtotal)), 2);
        v_discount_delta := v_new_discount - v_old_discount;

        if v_promo.budget_amount is not null
           and coalesce(v_promo.spent_amount, 0) + v_discount_delta > v_promo.budget_amount then
            raise exception 'promo_invalid:budget_exhausted';
        end if;

        update public.promo_codes
        set spent_amount = coalesce(spent_amount, 0) + v_discount_delta
        where id = v_promo.id;

        update public.promo_redemptions
        set discount_amount = v_new_discount
        where ride_id = v_ride.id;
    end if;

    update public.rides r
    set price_before_discount = v_subtotal,
        discount_amount = v_new_discount,
        price = round(greatest(0, v_subtotal - v_new_discount), 2),
        pricing_snapshot = coalesce(r.pricing_snapshot, '{}'::jsonb)
            || jsonb_build_object(
                'subtotal', v_subtotal,
                'discount', v_new_discount,
                'finalPrice', round(greatest(0, v_subtotal - v_new_discount), 2),
                'clientSubtotalFloor', v_floor,
                'clientSubtotalFloorApplied', v_floor > coalesce(v_ride.price_before_discount, v_ride.price, 0)
            )
    where r.id = v_ride.id
    returning jsonb_build_object(
        'rideId', r.id,
        'price', r.price,
        'status', r.status,
        'quote', r.pricing_snapshot,
        'idempotentReplay', coalesce((v_created->>'idempotentReplay')::boolean, false)
    ) into v_result;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_ride_request_v5(p_client_request_id uuid, p_pickup text, p_dropoff text, p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_route_duration_min numeric DEFAULT NULL::numeric, p_stops jsonb DEFAULT '[]'::jsonb, p_promo_code text DEFAULT NULL::text, p_passenger_phone text DEFAULT NULL::text, p_delivery_info jsonb DEFAULT NULL::jsonb, p_payer text DEFAULT NULL::text, p_cod_amount numeric DEFAULT NULL::numeric, p_terms_version text DEFAULT NULL::text, p_client_subtotal_floor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid := auth.uid();
    v_stops_count integer := 0;
    v_quote jsonb;
    v_created jsonb;
    v_ride_id bigint;
    v_replay boolean := false;
    v_result jsonb;
begin
    if v_user_id is null then
        raise exception 'authentication_required' using errcode = '42501';
    end if;

    if jsonb_typeof(coalesce(p_stops, '[]'::jsonb)) = 'array' then
        v_stops_count := jsonb_array_length(coalesce(p_stops, '[]'::jsonb));
    end if;

    v_quote := public.higo_quote_ride_v4(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        p_route_duration_min,
        v_stops_count,
        p_promo_code,
        v_user_id,
        p_client_subtotal_floor
    );

    if coalesce(trim(p_promo_code), '') <> ''
       and not coalesce((v_quote->>'promoValid')::boolean, false) then
        raise exception 'promo_invalid:%', coalesce(v_quote->>'promoError', 'unknown');
    end if;

    v_created := public.create_ride_request_v4(
        p_client_request_id,
        p_pickup,
        p_dropoff,
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        p_stops,
        p_promo_code,
        p_passenger_phone,
        p_delivery_info,
        p_payer,
        p_cod_amount,
        p_terms_version,
        (v_quote->>'chargedSubtotal')::numeric
    );

    v_ride_id := nullif(v_created->>'rideId', '')::bigint;
    v_replay := coalesce((v_created->>'idempotentReplay')::boolean, false);
    if v_ride_id is null then
        raise exception 'ride_creation_failed';
    end if;

    if not v_replay then
        update public.rides r
        set quoted_distance_km = (v_quote->>'distanceKm')::numeric,
            quoted_duration_min = (v_quote->>'durationMin')::numeric,
            pricing_version = (v_quote->>'pricingVersion')::integer,
            pricing_model = v_quote->>'pricingModel',
            pricing_multiplier = (v_quote->>'surgeMultiplier')::numeric,
            pricing_multiplier_reason = v_quote->>'multiplierReason',
            pricing_base_amount = (v_quote->>'base')::numeric,
            pricing_distance_amount = (v_quote->>'distanceAmount')::numeric,
            pricing_time_amount = (v_quote->>'timeAmount')::numeric,
            pricing_stops_amount = (v_quote->>'stopsAmount')::numeric,
            pricing_extras_amount = (v_quote->>'extrasAmount')::numeric,
            pricing_minimum_fare = (v_quote->>'minimumFare')::numeric,
            price_before_discount = (v_quote->>'subtotal')::numeric,
            discount_amount = (v_quote->>'discount')::numeric,
            price = (v_quote->>'finalPrice')::numeric,
            pricing_snapshot = v_quote
        where r.id = v_ride_id
          and r.user_id = v_user_id;

        insert into public.pricing_quote_audit(
            ride_id, user_id, rollout_mode, model_applied, pilot_bucket,
            vehicle_type, service_type, distance_km, duration_min,
            legacy_subtotal, model_subtotal, charged_subtotal, quote
        ) values (
            v_ride_id,
            v_user_id,
            v_quote->>'rolloutMode',
            coalesce((v_quote->>'modelApplied')::boolean, false),
            nullif(v_quote->>'pilotBucket', '')::integer,
            v_quote->>'vehicleType',
            v_quote->>'serviceType',
            (v_quote->>'distanceKm')::numeric,
            (v_quote->>'durationMin')::numeric,
            (v_quote->>'legacySubtotal')::numeric,
            (v_quote->>'modelSubtotal')::numeric,
            (v_quote->>'chargedSubtotal')::numeric,
            v_quote
        ) on conflict (ride_id) do nothing;
    end if;

    select jsonb_build_object(
        'rideId', r.id,
        'price', r.price,
        'status', r.status,
        'quote', r.pricing_snapshot,
        'idempotentReplay', v_replay
    )
    into v_result
    from public.rides r
    where r.id = v_ride_id
      and r.user_id = v_user_id;

    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.credit_pending_referral(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_ref public.referrals%ROWTYPE;
BEGIN
    SELECT * INTO v_ref FROM public.referrals
     WHERE referred_id = p_user_id AND status = 'pending'
     LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', FALSE, 'message', 'Sin referido pendiente');
    END IF;

    -- Crédito a ambos
    UPDATE public.profiles
       SET referral_credit_balance = COALESCE(referral_credit_balance, 0) + v_ref.credit_amount
     WHERE id IN (v_ref.referrer_id, v_ref.referred_id);

    UPDATE public.referrals
       SET status = 'credited', credited_at = NOW()
     WHERE id = v_ref.id;

    RETURN jsonb_build_object('ok', TRUE, 'credit_amount', v_ref.credit_amount);
END;
$function$;

CREATE OR REPLACE FUNCTION public.delivery_analytics(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  WITH base AS (
    SELECT r.* FROM public.rides r
     WHERE r.service_type = 'delivery'
       AND r.created_at >= p_from
       AND r.created_at <  p_to
  ),
  totals AS (
    SELECT
      COUNT(*)                                         AS total,
      COUNT(*) FILTER (WHERE status = 'completed')     AS completed,
      COUNT(*) FILTER (WHERE status = 'cancelled')     AS cancelled,
      AVG(EXTRACT(EPOCH FROM (delivered_at - picked_up_at))/60)
        FILTER (WHERE picked_up_at IS NOT NULL AND delivered_at IS NOT NULL)
        AS avg_pickup_to_delivery_min
    FROM base
  ),
  claims AS (
    SELECT COUNT(*) AS total_claims
      FROM public.delivery_claims c
      JOIN base b ON b.id = c.ride_id
  ),
  by_vehicle AS (
    SELECT jsonb_object_agg(ride_type, c) AS data
    FROM (SELECT ride_type, COUNT(*) c FROM base GROUP BY ride_type) v
  ),
  by_weight AS (
    SELECT jsonb_object_agg(bucket, c) AS data
    FROM (
      SELECT COALESCE(delivery_info->>'package_weight_kg','unknown') bucket,
             COUNT(*) c
        FROM base
       GROUP BY 1
    ) w
  ),
  top_dest AS (
    SELECT jsonb_agg(jsonb_build_object('dropoff', dropoff, 'count', c)
                     ORDER BY c DESC) AS data
      FROM (
        SELECT dropoff, COUNT(*) c FROM base
         GROUP BY dropoff
         ORDER BY c DESC
         LIMIT 10
      ) t
  )
  SELECT jsonb_build_object(
    'total',              totals.total,
    'completed',          totals.completed,
    'cancelled',          totals.cancelled,
    'success_rate',       CASE WHEN totals.total > 0
                               THEN ROUND(totals.completed::numeric / totals.total, 4)
                               ELSE 0 END,
    'avg_pickup_to_delivery_min',
                          ROUND(COALESCE(totals.avg_pickup_to_delivery_min, 0)::numeric, 1),
    'claims_total',       claims.total_claims,
    'claims_rate',        CASE WHEN totals.total > 0
                               THEN ROUND(claims.total_claims::numeric / totals.total, 4)
                               ELSE 0 END,
    'by_vehicle',         COALESCE(by_vehicle.data, '{}'::jsonb),
    'by_weight',          COALESCE(by_weight.data, '{}'::jsonb),
    'top_destinations',   COALESCE(top_dest.data, '[]'::jsonb)
  )
    INTO v_result
    FROM totals, claims, by_vehicle, by_weight, top_dest;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.driver_accept_ride_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile public.profiles%rowtype;
    v_ride jsonb;
begin
    v_profile := public.higo_assert_driver_operational();

    update public.rides r
    set driver_id = v_profile.id,
        status = 'accepted',
        accepted_at = coalesce(r.accepted_at, now())
    where r.id = p_ride_id
      and r.status = 'requested'
      and r.driver_id is null
    returning to_jsonb(r) into v_ride;

    if v_ride is null then
        select to_jsonb(r) into v_ride
        from public.rides r
        where r.id = p_ride_id
          and r.driver_id = v_profile.id
          and r.status in ('accepted','in_progress','arrived_at_dropoff');
        if v_ride is null then
            raise exception 'ride_unavailable';
        end if;
        return v_ride;
    end if;

    perform public.higo_log_ride_event(
        p_ride_id, 'requested', 'accepted', 'driver.accept', '{}'::jsonb
    );
    return v_ride;
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_complete_ride_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ride public.rides%rowtype;
    v_result jsonb;
    v_is_delivery boolean;
begin
    perform public.higo_assert_driver_operational();
    select * into v_ride
    from public.rides r
    where r.id = p_ride_id
      and r.driver_id = auth.uid()
    for update;

    if not found then raise exception 'ride_not_assigned'; end if;
    if v_ride.status = 'completed' then return to_jsonb(v_ride); end if;
    if v_ride.status not in ('in_progress','arrived_at_dropoff') then
        raise exception 'invalid_ride_transition';
    end if;

    v_is_delivery := v_ride.service_type = 'delivery' or v_ride.delivery_info is not null;
    if v_is_delivery and v_ride.delivery_pod_url is null then
        raise exception 'delivery_pod_required';
    end if;
    if v_is_delivery and coalesce(v_ride.cod_amount, 0) > 0
       and not coalesce(v_ride.cod_collected, false) then
        raise exception 'cod_confirmation_required';
    end if;

    update public.rides r
    set status = 'completed',
        completed_at = coalesce(r.completed_at, now())
    where r.id = p_ride_id
    returning to_jsonb(r) into v_result;

    perform public.higo_log_ride_event(
        p_ride_id, v_ride.status, 'completed', 'driver.complete', '{}'::jsonb
    );
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_has_active_membership(p_driver_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
    SELECT EXISTS (
        SELECT 1
        FROM public.driver_memberships
        WHERE driver_id = p_driver_id
          AND status = 'active'
          AND expires_at > NOW()
    );
$function$;

CREATE OR REPLACE FUNCTION public.driver_is_fully_approved(p_uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT COALESCE((
        SELECT COUNT(DISTINCT document_type) = 6
          FROM public.driver_documents
         WHERE user_id = p_uid
           AND status  = 'approved'
           AND document_type IN (
               'cedula', 'licencia', 'rcv', 'vehicle_photo',
               'circulacion', 'cert_salud'
           )
    ), false);
$function$;

CREATE OR REPLACE FUNCTION public.driver_list_ride_offers(p_limit integer DEFAULT 20)
 RETURNS TABLE(offer_id bigint, expires_at timestamp with time zone, distance_km numeric, score numeric, ride jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    perform public.higo_assert_driver_operational();

    -- Expire or withdraw anything that can no longer be presented. This also
    -- removes stale offers generated before a driver changed vehicle/status.
    update public.ride_offers o
    set status = case when o.expires_at <= now() then 'expired' else 'withdrawn' end,
        responded_at = coalesce(o.responded_at, now())
    from public.rides r
    join public.profiles p on p.id = auth.uid()
    where o.driver_id = auth.uid()
      and r.id = o.ride_id
      and o.status = 'offered'
      and (
          o.expires_at <= now()
          or r.status <> 'requested'
          or r.driver_id is not null
          or p.status <> 'online'
          or public.higo_canonical_vehicle_type(p.vehicle_type)
             is distinct from public.higo_canonical_vehicle_type(r.ride_type)
      );

    return query
    select
        o.id,
        o.expires_at,
        o.distance_km,
        o.score,
        to_jsonb(r)
    from public.ride_offers o
    join public.rides r on r.id = o.ride_id
    join public.profiles p on p.id = o.driver_id
    where o.driver_id = auth.uid()
      and o.status = 'offered'
      and o.expires_at > now()
      and r.status = 'requested'
      and r.driver_id is null
      and p.status = 'online'
      and public.higo_canonical_vehicle_type(p.vehicle_type)
          = public.higo_canonical_vehicle_type(r.ride_type)
    order by o.score desc, o.offered_at desc
    limit greatest(1, least(coalesce(p_limit, 20), 50));
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_mark_arrival_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ride jsonb;
begin
    perform public.higo_assert_driver_operational();
    update public.rides r
    set arrived_at_pickup_at = coalesce(r.arrived_at_pickup_at, now())
    where r.id = p_ride_id
      and r.driver_id = auth.uid()
      and r.status = 'accepted'
    returning to_jsonb(r) into v_ride;

    if v_ride is null then
        select to_jsonb(r) into v_ride from public.rides r
        where r.id = p_ride_id and r.driver_id = auth.uid();
        if v_ride is null then raise exception 'ride_not_assigned'; end if;
    else
        perform public.higo_log_ride_event(
            p_ride_id, 'accepted', 'accepted', 'driver.arrived_pickup', '{}'::jsonb
        );
    end if;
    return v_ride;
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_mark_dropoff_arrival_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result jsonb;
begin
    perform public.higo_assert_driver_operational();
    update public.rides r
    set status = 'arrived_at_dropoff',
        arrived_at_dropoff_at = coalesce(r.arrived_at_dropoff_at, now())
    where r.id = p_ride_id
      and r.driver_id = auth.uid()
      and r.status = 'in_progress'
    returning to_jsonb(r) into v_result;

    if v_result is null then
        select to_jsonb(r) into v_result from public.rides r
        where r.id = p_ride_id and r.driver_id = auth.uid()
          and r.status in ('arrived_at_dropoff','completed');
        if v_result is null then raise exception 'invalid_ride_transition'; end if;
        return v_result;
    end if;

    perform public.higo_log_ride_event(
        p_ride_id, 'in_progress', 'arrived_at_dropoff', 'driver.arrived_dropoff', '{}'::jsonb
    );
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_membership_checkout()
 RETURNS TABLE(id uuid, code text, name text, vehicle_type text, period text, duration_days integer, amount numeric, currency text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_vehicle_type text;
begin
    select public.higo_canonical_vehicle_type(
        coalesce(nullif(p.vehicle_type, ''), nullif(p.vehicle_model, ''), 'standard')
    )
    into v_vehicle_type
    from public.profiles p
    where p.id = auth.uid()
      and p.role = 'driver';

    if v_vehicle_type is null then
        raise exception 'driver_profile_required' using errcode = '42501';
    end if;

    return query
    select
        mp.id,
        mp.code,
        mp.name,
        public.higo_canonical_vehicle_type(mp.vehicle_type),
        mp.period,
        mp.duration_days,
        mp.amount,
        mp.currency
    from public.driver_membership_plans mp
    where mp.active
      and public.higo_canonical_vehicle_type(mp.vehicle_type) = v_vehicle_type
    order by mp.duration_days, mp.amount;
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_set_online_status(p_online boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_uid uuid := auth.uid();
    v_profile public.profiles%rowtype;
    v_withdrawn integer := 0;
begin
    if v_uid is null then
        raise exception 'authentication required' using errcode = '42501';
    end if;

    select * into v_profile
    from public.profiles
    where id = v_uid
    for update;

    if not found or coalesce(v_profile.role::text, '') <> 'driver' then
        raise exception 'driver account required' using errcode = '42501';
    end if;

    if coalesce(p_online, false) then
        perform public.higo_assert_driver_operational();
        update public.profiles
        set status = 'online'
        where id = v_uid;
    else
        update public.profiles
        set status = 'offline'
        where id = v_uid;

        update public.ride_offers
        set status = 'withdrawn',
            responded_at = coalesce(responded_at, now())
        where driver_id = v_uid
          and status = 'offered';
        get diagnostics v_withdrawn = row_count;
    end if;

    return jsonb_build_object(
        'driverId', v_uid,
        'online', coalesce(p_online, false),
        'status', case when coalesce(p_online, false) then 'online' else 'offline' end,
        'withdrawnOffers', v_withdrawn
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.driver_start_ride_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ride public.rides%rowtype;
    v_wait_seconds integer := 0;
    v_wait_rate numeric := 0;
    v_wait_fee numeric := 0;
    v_result jsonb;
begin
    perform public.higo_assert_driver_operational();

    select * into v_ride
    from public.rides r
    where r.id = p_ride_id
      and r.driver_id = auth.uid()
    for update;

    if not found then raise exception 'ride_not_assigned'; end if;
    if v_ride.status in ('in_progress','arrived_at_dropoff','completed') then
        return to_jsonb(v_ride);
    end if;
    if v_ride.status <> 'accepted' then raise exception 'invalid_ride_transition'; end if;

    if v_ride.arrived_at_pickup_at is not null then
        v_wait_seconds := greatest(0, floor(extract(epoch from now() - v_ride.arrived_at_pickup_at))::integer);
    end if;

    select pc.wait_per_min into v_wait_rate
    from public.pricing_config pc
    where public.higo_canonical_vehicle_type(pc.vehicle_type)
          = public.higo_canonical_vehicle_type(v_ride.ride_type)
    limit 1;
    if v_wait_rate is null then
        v_wait_rate := case public.higo_canonical_vehicle_type(v_ride.ride_type)
            when 'moto' then 0.05 when 'van' then 0.10 else 0.08 end;
    end if;
    v_wait_fee := round(greatest(0, v_wait_seconds::numeric / 60 - 3) * v_wait_rate, 2);

    update public.rides r
    set status = 'in_progress',
        started_at = coalesce(r.started_at, now()),
        wait_seconds = v_wait_seconds,
        wait_fee = v_wait_fee,
        price = round(coalesce(r.price, 0) + v_wait_fee, 2)
    where r.id = p_ride_id
    returning to_jsonb(r) into v_result;

    perform public.higo_log_ride_event(
        p_ride_id, 'accepted', 'in_progress', 'driver.start',
        jsonb_build_object('wait_seconds', v_wait_seconds, 'wait_fee', v_wait_fee)
    );
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_order_update_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_merchant boolean;
BEGIN
  -- service_role (backend) y admins: sin restricciones
  IF v_uid IS NULL OR public.is_admin(v_uid) THEN
    RETURN NEW;
  END IF;

  -- Columnas financieras y de identidad: inmutables para todos los roles
  IF NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.store_id IS DISTINCT FROM OLD.store_id
     OR NEW.total IS DISTINCT FROM OLD.total
     OR NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee
     OR NEW.items IS DISTINCT FROM OLD.items THEN
    RAISE EXCEPTION 'orders: no se pueden modificar montos, items ni participantes';
  END IF;

  -- ── Cliente ──
  IF v_uid = OLD.customer_id THEN
    IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
      RAISE EXCEPTION 'orders: el cliente no puede cambiar el driver';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
      (NEW.status = 'PRODUCT_PAYMENT_REPORTED'
        AND OLD.status IN ('PENDING_PRODUCT_PAYMENT', 'PENDING_PAYMENT'))
      OR (NEW.status = 'DELIVERY_PAYMENT_REPORTED'
        AND OLD.status IN ('PICKED_UP', 'DRIVER_EN_ROUTE_TO_CUSTOMER', 'DELIVERY_PAYMENT_PENDING'))
      OR (NEW.status = 'CANCELLED'
        AND OLD.status IN ('PENDING_PRODUCT_PAYMENT', 'PENDING_PAYMENT', 'PRODUCT_PAYMENT_REPORTED'))
    ) THEN
      RAISE EXCEPTION 'orders: transición de estado no permitida para el cliente (% -> %)', OLD.status, NEW.status;
    END IF;
    RETURN NEW;
  END IF;

  -- ── Comercio dueño de la tienda ──
  SELECT EXISTS (
    SELECT 1 FROM public.stores s WHERE s.id = OLD.store_id AND s.owner_id = v_uid
  ) INTO v_is_merchant;

  IF v_is_merchant THEN
    IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
      RAISE EXCEPTION 'orders: el comercio no puede asignar drivers';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN (
      'PRODUCT_PAYMENT_VERIFIED', 'PAYMENT_VERIFIED', 'PREPARING',
      'READY_FOR_DRIVER_MATCH', 'READY_TO_DISPATCH',
      'DRIVER_CANDIDATE_BROADCASTED', 'CANCELLED'
    ) THEN
      RAISE EXCEPTION 'orders: transición de estado no permitida para el comercio (% -> %)', OLD.status, NEW.status;
    END IF;
    RETURN NEW;
  END IF;

  -- ── Driver asignado: avanza su entrega, no se desasigna ──
  IF v_uid = OLD.driver_id THEN
    IF NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
      RAISE EXCEPTION 'orders: el driver no puede transferir la orden';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN (
      'DRIVER_EN_ROUTE_TO_STORE', 'PICKED_UP', 'DRIVER_EN_ROUTE_TO_CUSTOMER',
      'DELIVERY_PAYMENT_PENDING', 'DELIVERY_PAYMENT_CONFIRMED', 'DELIVERED'
    ) THEN
      RAISE EXCEPTION 'orders: transición de estado no permitida para el driver (% -> %)', OLD.status, NEW.status;
    END IF;
    RETURN NEW;
  END IF;

  -- ── Driver aceptando una orden despachable sin asignar ──
  IF OLD.driver_id IS NULL
     AND OLD.status IN ('READY_FOR_DRIVER_MATCH', 'DRIVER_CANDIDATE_BROADCASTED', 'READY_TO_DISPATCH')
     AND public.is_driver(v_uid)
     AND NEW.driver_id = v_uid
     AND NEW.status IN ('DRIVER_ASSIGNED', 'DRIVER_EN_ROUTE_TO_STORE') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'orders: actualización no autorizada';
END;
$function$;

CREATE OR REPLACE FUNCTION public.gen_referral_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';  -- sin O, 0, I, 1
    code  TEXT := '';
    i INT;
BEGIN
    FOR i IN 1..6 LOOP
        code := code || substr(chars, 1 + (random() * (length(chars) - 1))::int, 1);
    END LOOP;
    RETURN code;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_active_pricing_multiplier(p_vehicle_type text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_local  TIMESTAMPTZ := timezone('America/Caracas', now());
    v_hour   INT         := EXTRACT(HOUR FROM v_local);
    v_dow    INT         := EXTRACT(DOW  FROM v_local); -- 0=Sun..6=Sat
    v_mult   NUMERIC     := 1.0;
BEGIN
    SELECT COALESCE(MAX(multiplier), 1.0) INTO v_mult
      FROM public.pricing_rules
     WHERE active = true
       AND (vehicle_type IS NULL OR vehicle_type = p_vehicle_type)
       AND (day_of_week  IS NULL OR v_dow = ANY(day_of_week))
       AND (
           -- Sin filtro horario.
           (hour_start IS NULL AND hour_end IS NULL)
           OR
           -- Rango normal: [start, end).
           (hour_start IS NOT NULL AND hour_end IS NOT NULL
            AND hour_start <= hour_end
            AND v_hour >= hour_start AND v_hour < hour_end)
           OR
           -- Rango que cruza medianoche: [start, 24) U [0, end).
           (hour_start IS NOT NULL AND hour_end IS NOT NULL
            AND hour_start > hour_end
            AND (v_hour >= hour_start OR v_hour < hour_end))
       )
       AND (starts_at IS NULL OR starts_at <= now())
       AND (ends_at   IS NULL OR ends_at   >  now());
    RETURN COALESCE(v_mult, 1.0);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_nearby_drivers(lat double precision, lng double precision, radius_km double precision)
 RETURNS SETOF profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  return query
  select *
  from profiles
  where 
    role = 'driver' 
    and ST_DWithin(
      location,
      ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography,
      radius_km * 1000
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_nearby_rides(driver_lat double precision, driver_lng double precision, radius_km double precision, driver_vehicle_type text)
 RETURNS SETOF rides
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  target_type text;
begin
  -- Normalize vehicle type logic (similar to frontend)
  if driver_vehicle_type = 'auto' or driver_vehicle_type = 'carro' then
    driver_vehicle_type := 'standard';
  end if;
  return query
  select *
  from rides
  where 
    status = 'requested'
    -- Spatial Filter (5km)
    and ST_DWithin(
      pickup_location,
      ST_SetSRID(ST_MakePoint(driver_lng, driver_lat), 4326)::geography,
      radius_km * 1000
    )
    -- Vehicle Type Filter
    and (
      (driver_vehicle_type = 'moto' and (ride_type = 'moto'))
      or
      ((driver_vehicle_type = 'van' or driver_vehicle_type = 'camioneta') and (ride_type = 'van'))
      or
      (driver_vehicle_type = 'standard' and (ride_type = 'standard' or ride_type = 'car' or ride_type is null))
    )
    order by created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_profile(p_id uuid)
 RETURNS TABLE(id uuid, full_name text, avatar_url text, role text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT p.id, p.full_name, p.avatar_url, p.role
      FROM public.profiles p
     WHERE p.id = p_id
       AND auth.uid() IS NOT NULL;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_tracking(p_token uuid)
 RETURNS TABLE(status text, service_type text, pickup text, dropoff text, picked_up_at timestamp with time zone, arrived_at_dropoff_at timestamp with time zone, delivered_at timestamp with time zone, driver_display_name text, driver_lat numeric, driver_lng numeric, delivery_pod_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    r.status,
    r.service_type,
    r.pickup,
    r.dropoff,
    r.picked_up_at,
    r.arrived_at_dropoff_at,
    r.delivered_at,
    p.display_name,
    CASE WHEN r.status IN ('accepted','in_progress','arrived_at_dropoff')
         THEN p.current_lat ELSE NULL END,
    CASE WHEN r.status IN ('accepted','in_progress','arrived_at_dropoff')
         THEN p.current_lng ELSE NULL END,
    r.delivery_pod_url
  FROM public.delivery_tracking_tokens t
  JOIN public.rides r ON r.id = t.ride_id
  LEFT JOIN public.profiles p ON p.id = r.driver_id
  WHERE t.token = p_token
    AND t.expires_at > NOW()
    AND r.service_type = 'delivery'
  LIMIT 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.higo_admin_can(p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_role text := public.higo_admin_role();
begin
    if v_role is null then return false; end if;
    if v_role = 'super_admin' then return true; end if;
    if p_permission in ('view_dashboard','view_analytics') then return true; end if;
    if v_role = 'operations' and p_permission in ('manage_drivers','manage_operations','manage_pricing','manage_zones','manage_disputes') then return true; end if;
    if v_role = 'support' and p_permission in ('manage_support','manage_disputes','view_users') then return true; end if;
    if v_role = 'finance' and p_permission in ('manage_memberships','view_finance','manage_disputes') then return true; end if;
    if v_role = 'viewer' and p_permission in ('view_users') then return true; end if;
    return false;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_admin_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce((
        select r.staff_role
        from public.admin_staff_roles r
        where r.user_id = auth.uid() and r.active
    ), case when public.higo_is_admin() then 'viewer' else null end);
$function$;

CREATE OR REPLACE FUNCTION public.higo_assert_admin(p_permission text, p_sensitive boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_require_mfa boolean := false;
    v_aal text := coalesce(auth.jwt()->>'aal', 'aal1');
begin
    if not public.higo_admin_can(p_permission) then
        raise exception 'admin_permission_denied' using errcode = '42501';
    end if;
    select require_mfa into v_require_mfa from public.admin_security_settings where singleton;
    if p_sensitive and v_require_mfa and v_aal <> 'aal2' then
        raise exception 'admin_mfa_required' using errcode = '42501';
    end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_assert_driver_operational()
 RETURNS profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile public.profiles%rowtype;
    v_has_membership boolean := false;
begin
    select * into v_profile
    from public.profiles p
    where p.id = auth.uid()
      and p.role = 'driver';

    if not found then
        raise exception 'driver_role_required' using errcode = '42501';
    end if;
    if v_profile.archived_at is not null then
        raise exception 'driver_archived' using errcode = '42501';
    end if;
    if v_profile.suspended_at is not null then
        raise exception 'driver_suspended' using errcode = '42501';
    end if;

    select exists(
        select 1
        from public.driver_memberships dm
        where dm.driver_id = auth.uid()
          and dm.voided_at is null
          and dm.status = 'active'
          and dm.expires_at >= now()
    )
    into v_has_membership;

    if not v_has_membership
       and not (v_profile.subscription_override_until is not null
                and v_profile.subscription_override_until >= now()) then
        raise exception 'membership_required' using errcode = '42501';
    end if;

    return v_profile;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_audit_ride_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status is distinct from old.status then
        perform public.higo_log_ride_event(
            new.id,
            old.status,
            new.status,
            'ride.status_transition',
            jsonb_build_object(
                'driver_id', new.driver_id,
                'passenger_id', new.user_id,
                'source', 'table_trigger'
            )
        );
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_before jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
    v_after jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
    v_id text := coalesce(v_after->>'id', v_before->>'id', v_after->>'user_id', v_before->>'user_id');
begin
    if auth.uid() is not null then
        insert into public.admin_audit_log(actor_id,action,entity_type,entity_id,before_data,after_data,metadata)
        values(auth.uid(),lower(tg_op),tg_table_name,v_id,v_before,v_after,jsonb_build_object('schema',tg_table_schema));
    end if;
    return coalesce(new,old);
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_canonical_vehicle_type(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select case lower(trim(coalesce(p_value, '')))
        when 'moto' then 'moto'
        when 'motorcycle' then 'moto'
        when 'motocicleta' then 'moto'
        when 'van' then 'van'
        when 'camioneta' then 'van'
        when 'pickup' then 'van'
        when 'car' then 'standard'
        when 'carro' then 'standard'
        when 'auto' then 'standard'
        when 'standard' then 'standard'
        else 'standard'
    end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_capture_fair_dispatch_shadow(p_ride_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_count integer := 0;
begin
    delete from public.fair_dispatch_shadow_candidates where ride_id = p_ride_id;

    insert into public.fair_dispatch_shadow_candidates(
        ride_id,
        driver_id,
        predicted_wave,
        rank_position,
        distance_km,
        score,
        distance_score,
        wait_score,
        trip_deficit_score,
        offer_deficit_score,
        freshness_score,
        penalty_score,
        completed_rides_7d,
        offers_received_24h
    )
    select
        p_ride_id,
        ranked.driver_id,
        case
            when ranked.distance_km <= 3 and ranked.rank_position <= 3 then 1
            when ranked.distance_km <= 5 and ranked.rank_position <= 8 then 2
            when ranked.distance_km <= 8 and ranked.rank_position <= 18 then 3
            else 4
        end,
        ranked.rank_position,
        ranked.distance_km,
        ranked.score,
        ranked.distance_score,
        ranked.wait_score,
        ranked.trip_deficit_score,
        ranked.offer_deficit_score,
        ranked.freshness_score,
        ranked.penalty_score,
        ranked.completed_rides_7d,
        ranked.offers_received_24h
    from (
        select
            candidates.*,
            row_number() over (
                order by candidates.score desc, candidates.distance_km,
                         candidates.available_since, candidates.driver_id
            )::integer as rank_position
        from public.higo_rank_dispatch_candidates(p_ride_id, 10, 1) candidates
    ) ranked;

    get diagnostics v_count = row_count;
    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_claim_driver_application_upload_token(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_token public.driver_application_upload_tokens%rowtype;
    v_application public.driver_applications%rowtype;
    v_claim_id uuid := gen_random_uuid();
begin
    select * into v_token
      from public.driver_application_upload_tokens
     where token_hash = p_token_hash
       and used_at is null
       and expires_at > now()
       and (claimed_at is null or claimed_at < now() - interval '15 minutes')
     for update;

    if not found then return null; end if;

    select * into v_application
      from public.driver_applications
     where id = v_token.application_id
     for update;

    if not found or v_application.status not in ('documents_requested','correction_requested') then
        return null;
    end if;

    update public.driver_application_upload_tokens
       set claim_id = v_claim_id,
           claimed_at = now(),
           last_used_at = now()
     where id = v_token.id;

    return to_jsonb(v_application) || jsonb_build_object(
        'upload_claim_id', v_claim_id,
        'upload_token_id', v_token.id,
        'upload_expires_at', v_token.expires_at
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_complete_driver_application_upload(p_token_hash text, p_claim_id uuid, p_documents_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_token public.driver_application_upload_tokens%rowtype;
    v_before public.driver_applications%rowtype;
    v_after public.driver_applications%rowtype;
begin
    if coalesce(p_documents_count, 0) < 1 then
        raise exception 'no_documents' using errcode = '22023';
    end if;

    select * into v_token
      from public.driver_application_upload_tokens
     where token_hash = p_token_hash
       and claim_id = p_claim_id
       and claimed_at >= now() - interval '15 minutes'
       and used_at is null
       and expires_at > now()
     for update;

    if not found then
        raise exception 'invalid_or_expired_upload_claim' using errcode = '28000';
    end if;

    select * into v_before
      from public.driver_applications
     where id = v_token.application_id
     for update;

    if not found then
        raise exception 'driver_application_not_found' using errcode = 'P0002';
    end if;
    if v_before.status not in ('documents_requested','correction_requested') then
        raise exception 'documents_not_expected' using errcode = '22023';
    end if;

    update public.driver_application_upload_tokens
       set used_at = now(),
           last_used_at = now(),
           claim_id = null,
           claimed_at = null
     where id = v_token.id;

    update public.driver_applications
       set status = 'documents_submitted',
           status_reason = null,
           last_status_changed_at = now(),
           last_status_changed_by = null
     where id = v_before.id
     returning * into v_after;

    insert into public.driver_application_events(
        application_id, actor_type, event_type, from_status, to_status, metadata
    ) values (
        v_before.id, 'applicant', 'documents_submitted', v_before.status,
        'documents_submitted', jsonb_build_object('documents_count', p_documents_count)
    );

    return to_jsonb(v_after);
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_current_driver_has_active_offer(p_ride_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select public.higo_driver_has_active_offer(
        p_ride_id,
        auth.uid()
    );
$function$;

CREATE OR REPLACE FUNCTION public.higo_current_user_is_driver()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select exists(
        select 1
        from public.profiles p
        where p.id = auth.uid()
          and p.role = 'driver'
    );
$function$;

CREATE OR REPLACE FUNCTION public.higo_directed_offers_enabled()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce((
        select directed_ride_offers
        from public.platform_runtime_flags
        where singleton
    ), false);
$function$;

CREATE OR REPLACE FUNCTION public.higo_dispatch_new_ride()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status <> 'requested' then
        return new;
    end if;

    if public.higo_fair_dispatch_shadow_enabled() then
        perform public.higo_capture_fair_dispatch_shadow(new.id);
    end if;

    if public.higo_fair_progressive_dispatch_enabled() then
        perform public.higo_start_progressive_dispatch(new.id);
    elsif public.higo_directed_offers_enabled() then
        perform public.higo_dispatch_ride(new.id, 20, 30);
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_dispatch_ride(p_ride_id bigint, p_limit integer DEFAULT 20, p_radius_km numeric DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ride public.rides%rowtype;
    v_count integer := 0;
    v_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
    v_radius numeric := greatest(1, least(coalesce(p_radius_km, 30), 100));
begin
    select * into v_ride
    from public.rides r
    where r.id = p_ride_id
      and r.status = 'requested';

    if not found or v_ride.pickup_lat is null or v_ride.pickup_lng is null then
        return 0;
    end if;

    insert into public.ride_offers(
        ride_id, driver_id, distance_km, score, expires_at
    )
    select
        v_ride.id,
        candidates.driver_id,
        candidates.distance_km,
        -- Prefer proximity, then recently updated GPS.
        round((100 - least(candidates.distance_km, 100))
            + greatest(0, 10 - candidates.location_age_minutes), 4),
        now() + interval '3 minutes'
    from (
        select
            p.id as driver_id,
            public.higo_haversine_km(
                p.curr_lat::double precision,
                p.curr_lng::double precision,
                v_ride.pickup_lat::double precision,
                v_ride.pickup_lng::double precision
            ) as distance_km,
            extract(epoch from (now() - coalesce(p.last_location_update, p.updated_at))) / 60
                as location_age_minutes
        from public.profiles p
        where p.role = 'driver'
          and p.status = 'online'
          and p.archived_at is null
          and p.suspended_at is null
          and p.curr_lat is not null
          and p.curr_lng is not null
          and coalesce(p.last_location_update, p.updated_at) >= now() - interval '3 minutes'
          and public.higo_canonical_vehicle_type(p.vehicle_type)
              = public.higo_canonical_vehicle_type(v_ride.ride_type)
          and (
              exists (
                  select 1
                  from public.driver_memberships dm
                  where dm.driver_id = p.id
                    and dm.voided_at is null
                    and dm.status = 'active'
                    and dm.expires_at >= now()
              )
              or (
                  p.subscription_override_until is not null
                  and p.subscription_override_until >= now()
              )
          )
    ) candidates
    where candidates.distance_km <= v_radius
    order by candidates.distance_km, candidates.location_age_minutes
    limit v_limit
    on conflict (ride_id, driver_id) do update
    set status = case
            when public.ride_offers.status = 'accepted' then 'accepted'
            else 'offered'
        end,
        distance_km = excluded.distance_km,
        score = excluded.score,
        offered_at = now(),
        expires_at = excluded.expires_at;

    get diagnostics v_count = row_count;
    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_dispatch_wave(p_ride_id bigint, p_wave_number integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_config public.fair_dispatch_wave_config%rowtype;
    v_dispatch public.ride_dispatches%rowtype;
    v_count integer := 0;
begin
    select * into v_config
    from public.fair_dispatch_wave_config
    where wave_number = p_wave_number and enabled;

    if not found then
        return 0;
    end if;

    select * into v_dispatch
    from public.ride_dispatches
    where ride_id = p_ride_id
      and status = 'active'
    for update;

    if not found or v_dispatch.dispatch_deadline_at <= now() then
        return 0;
    end if;

    -- Acceptance updates the same rides row. Holding this lock until the wave
    -- insert commits prevents late offers from appearing after a driver wins.
    perform 1
    from public.rides r
    where r.id = p_ride_id
      and r.status = 'requested'
      and r.driver_id is null
    for update;

    if not found then
        return 0;
    end if;

    insert into public.ride_offers(
        ride_id,
        driver_id,
        distance_km,
        score,
        offered_at,
        expires_at,
        wave_number,
        rank_position,
        distance_score,
        wait_score,
        trip_deficit_score,
        offer_deficit_score,
        freshness_score,
        penalty_score,
        notification_status
    )
    select
        p_ride_id,
        ranked.driver_id,
        ranked.distance_km,
        ranked.score,
        now(),
        v_dispatch.dispatch_deadline_at,
        p_wave_number,
        ranked.rank_position,
        ranked.distance_score,
        ranked.wait_score,
        ranked.trip_deficit_score,
        ranked.offer_deficit_score,
        ranked.freshness_score,
        ranked.penalty_score,
        'pending'
    from (
        select
            candidates.*,
            (row_number() over (
                order by candidates.score desc, candidates.distance_km,
                         candidates.available_since, candidates.driver_id
            ))::integer as rank_position
        from public.higo_rank_dispatch_candidates(
            p_ride_id,
            v_config.radius_km,
            v_config.fairness_multiplier
        ) candidates
    ) ranked
    order by ranked.rank_position
    limit v_config.add_limit
    on conflict (ride_id, driver_id) do nothing;

    get diagnostics v_count = row_count;

    update public.ride_dispatches
    set current_wave = greatest(current_wave, p_wave_number),
        offers_created = offers_created + v_count,
        updated_at = now()
    where ride_id = p_ride_id;

    return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_driver_application_transition_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select p_from = p_to or case p_from
        when 'pending_delivery' then p_to in ('received','delivery_failed')
        when 'delivery_failed' then p_to in ('received','rejected')
        when 'received' then p_to in ('under_review','documents_requested','waitlist','rejected')
        when 'under_review' then p_to in ('documents_requested','approved','waitlist','rejected')
        when 'documents_requested' then p_to in ('documents_submitted','correction_requested','rejected')
        when 'documents_submitted' then p_to in ('correction_requested','approved','rejected')
        when 'correction_requested' then p_to in ('documents_submitted','documents_requested','rejected')
        when 'approved' then p_to in ('converted','rejected')
        when 'waitlist' then p_to in ('under_review','rejected')
        else false
    end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_driver_has_active_offer(p_ride_id bigint, p_driver_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists(
        select 1
        from public.ride_offers o
        where o.ride_id = p_ride_id
          and o.driver_id = p_driver_id
          and o.status = 'offered'
          and o.expires_at > now()
    );
$function$;

CREATE OR REPLACE FUNCTION public.higo_expand_due_dispatches(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    dispatch_row public.ride_dispatches%rowtype;
    v_next_wave integer;
    v_created integer;
    v_wave_limit integer;
    v_following_delay integer;
    v_processed integer := 0;
begin
    update public.ride_offers
    set status = 'expired',
        responded_at = coalesce(responded_at, now()),
        notification_status = case
            when notification_status = 'pending' then 'skipped'
            else notification_status
        end
    where status = 'offered'
      and expires_at <= now();

    update public.ride_dispatches d
    set status = case
            when r.status = 'cancelled' then 'cancelled'
            when r.status = 'completed' then 'completed'
            when r.status <> 'requested' or r.driver_id is not null then 'accepted'
            else 'expired'
        end,
        next_wave_at = null,
        completed_at = coalesce(d.completed_at, now()),
        updated_at = now()
    from public.rides r
    where d.ride_id = r.id
      and d.status = 'active'
      and (
          r.status <> 'requested'
          or r.driver_id is not null
          or d.dispatch_deadline_at <= now()
      );

    if not public.higo_fair_progressive_dispatch_enabled() then
        return 0;
    end if;

    for dispatch_row in
        select d.*
        from public.ride_dispatches d
        join public.rides r on r.id = d.ride_id
        where d.status = 'active'
          and d.next_wave_at is not null
          and d.next_wave_at <= now()
          and d.dispatch_deadline_at > now()
          and r.status = 'requested'
          and r.driver_id is null
        order by d.next_wave_at, d.ride_id
        for update of d skip locked
        limit greatest(1, least(coalesce(p_limit, 50), 200))
    loop
        v_next_wave := dispatch_row.current_wave + 1;

        select add_limit into v_wave_limit
        from public.fair_dispatch_wave_config
        where wave_number = v_next_wave and enabled;

        if v_wave_limit is null then
            update public.ride_dispatches
            set status = 'exhausted', next_wave_at = null, updated_at = now()
            where ride_id = dispatch_row.ride_id;
            continue;
        end if;

        v_created := public.higo_dispatch_wave(dispatch_row.ride_id, v_next_wave);

        select delay_seconds into v_following_delay
        from public.fair_dispatch_wave_config
        where wave_number = v_next_wave + 1 and enabled;

        update public.ride_dispatches
        set next_wave_at = case
                when v_following_delay is null then null
                when v_created < v_wave_limit then now()
                else started_at + make_interval(secs => v_following_delay)
            end,
            status = case when v_following_delay is null then 'exhausted' else 'active' end,
            updated_at = now()
        where ride_id = dispatch_row.ride_id
          and status = 'active';

        v_processed := v_processed + 1;
    end loop;

    return v_processed;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_fair_dispatch_shadow_enabled()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce((
        select fair_dispatch_shadow
        from public.platform_runtime_flags
        where singleton
    ), false);
$function$;

CREATE OR REPLACE FUNCTION public.higo_fair_progressive_dispatch_enabled()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce((
        select directed_ride_offers and fair_progressive_dispatch
        from public.platform_runtime_flags
        where singleton
    ), false);
$function$;

CREATE OR REPLACE FUNCTION public.higo_guard_ride_coverage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_actor uuid := auth.uid();
    v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
    v_is_admin boolean := false;
    v_is_database_repair boolean := session_user in ('postgres', 'supabase_admin');
    v_coverage boolean;
begin
    if coalesce(new.status, 'requested') <> 'requested' then
        return new;
    end if;

    if v_actor is not null then
        v_is_admin := public.higo_is_admin();
    end if;

    if v_is_service or v_is_admin or v_is_database_repair then
        return new;
    end if;

    if v_actor is null then
        raise exception 'authentication_required' using errcode = '42501';
    end if;
    if new.user_id is distinct from v_actor then
        raise exception 'ride_owner_mismatch' using errcode = '42501';
    end if;
    if new.pickup_lat is null or new.pickup_lng is null
       or new.dropoff_lat is null or new.dropoff_lng is null then
        raise exception 'ride_coordinates_required';
    end if;

    begin
        select public.is_within_coverage(
            new.pickup_lat::double precision,
            new.pickup_lng::double precision
        ) into v_coverage;
    exception
        when undefined_function then
            raise exception 'coverage_service_unavailable';
        when others then
            raise exception 'coverage_check_failed:%', sqlerrm;
    end;

    if not coalesce(v_coverage, false) then
        raise exception 'pickup_outside_coverage';
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_guard_ride_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_actor uuid := auth.uid();
    v_actor_role text;
    v_is_admin boolean := false;
    v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
    v_is_database_repair boolean := session_user in ('postgres', 'supabase_admin');
    v_allowed boolean := false;
    v_directed boolean := public.higo_directed_offers_enabled();
begin
    if new.status is not distinct from old.status then
        return new;
    end if;

    if v_actor is not null then
        select p.role into v_actor_role
        from public.profiles p
        where p.id = v_actor;
        v_is_admin := public.higo_is_admin();
    end if;

    if v_is_service or v_is_admin or v_is_database_repair then
        v_allowed := true;
    elsif old.status = 'requested' and new.status = 'accepted' then
        perform public.higo_assert_driver_operational();
        v_allowed := v_actor_role = 'driver'
            and new.driver_id = v_actor
            and old.driver_id is null
            and (
                not v_directed
                or public.higo_driver_has_active_offer(old.id, v_actor)
            );
    elsif old.status in ('requested', 'accepted') and new.status = 'cancelled' then
        v_allowed := old.user_id = v_actor;
    elsif old.status = 'accepted' and new.status = 'in_progress' then
        v_allowed := old.driver_id = v_actor and new.driver_id = v_actor;
    elsif old.status = 'in_progress' and new.status = 'arrived_at_dropoff' then
        v_allowed := old.driver_id = v_actor and new.driver_id = v_actor;
    elsif old.status in ('in_progress', 'arrived_at_dropoff') and new.status = 'completed' then
        v_allowed := old.driver_id = v_actor and new.driver_id = v_actor;
    end if;

    if not v_allowed then
        raise exception 'invalid_ride_transition:%->%', old.status, new.status
            using errcode = '42501';
    end if;

    if new.status = 'accepted' then
        new.accepted_at := coalesce(new.accepted_at, now());
    elsif new.status = 'in_progress' then
        new.started_at := coalesce(new.started_at, now());
    elsif new.status = 'arrived_at_dropoff' then
        new.arrived_at_dropoff_at := coalesce(new.arrived_at_dropoff_at, now());
    elsif new.status = 'completed' then
        new.completed_at := coalesce(new.completed_at, now());
    elsif new.status = 'cancelled' then
        new.cancelled_at := coalesce(new.cancelled_at, now());
        if old.user_id = v_actor and coalesce(trim(new.cancellation_reason), '') = '' then
            raise exception 'cancellation_reason_required';
        end if;
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_has_active_ride_offers(p_ride_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists(
        select 1
        from public.ride_offers o
        where o.ride_id = p_ride_id
          and o.status = 'offered'
          and o.expires_at > now()
    );
$function$;

CREATE OR REPLACE FUNCTION public.higo_haversine_km(p_lat1 double precision, p_lng1 double precision, p_lat2 double precision, p_lng2 double precision)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select (
        6371.0 * 2.0 * asin(
            least(1.0, sqrt(
                power(sin(radians(p_lat2 - p_lat1) / 2.0), 2) +
                cos(radians(p_lat1)) * cos(radians(p_lat2)) *
                power(sin(radians(p_lng2 - p_lng1) / 2.0), 2)
            ))
        )
    )::numeric;
$function$;

CREATE OR REPLACE FUNCTION public.higo_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1 from public.profiles p
        where p.id = auth.uid() and p.role = 'admin'
    );
$function$;

CREATE OR REPLACE FUNCTION public.higo_log_ride_event(p_ride_id bigint, p_from_status text, p_to_status text, p_event_type text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    -- RPCs and the table trigger may observe the same transition. Keep a
    -- single event per actor/from/to in a short transaction window.
    if exists (
        select 1
        from public.ride_state_events e
        where e.ride_id = p_ride_id
          and e.actor_id is not distinct from auth.uid()
          and e.from_status is not distinct from p_from_status
          and e.to_status = p_to_status
          and e.created_at >= now() - interval '3 seconds'
    ) then
        return;
    end if;

    insert into public.ride_state_events(
        ride_id, actor_id, from_status, to_status, event_type, metadata
    ) values (
        p_ride_id,
        auth.uid(),
        p_from_status,
        p_to_status,
        p_event_type,
        coalesce(p_metadata, '{}'::jsonb)
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_membership_status(p_expires_at timestamp with time zone, p_membership_status text, p_archived_at timestamp with time zone, p_suspended_at timestamp with time zone, p_override_until timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
    select case
        when p_archived_at is not null then 'archived'
        when p_suspended_at is not null then 'suspended'
        when p_override_until is not null and p_override_until >= now() then 'grace_period'
        when p_membership_status is null then 'no_membership'
        when p_membership_status <> 'active' then p_membership_status
        when p_expires_at < now() then 'expired'
        when p_expires_at <= now() + interval '7 days' then 'expiring_soon'
        else 'active'
    end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_pricing_bucket(p_user_id uuid)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select case
        when p_user_id is null then 100
        else mod(abs(hashtext(p_user_id::text)::bigint), 100)::integer
    end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_public_driver_application_status(p_application_code text, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_application public.driver_applications%rowtype;
    v_label text;
    v_next_step text;
begin
    select * into v_application
      from public.driver_applications
     where application_code = upper(trim(p_application_code))
       and lower(email) = lower(trim(p_email));

    if not found then return null; end if;

    select
        case v_application.status
            when 'pending_delivery' then 'Solicitud en proceso'
            when 'delivery_failed' then 'Pendiente de confirmación'
            when 'received' then 'Solicitud recibida'
            when 'under_review' then 'En revisión'
            when 'documents_requested' then 'Documentos solicitados'
            when 'documents_submitted' then 'Documentos recibidos'
            when 'correction_requested' then 'Corrección solicitada'
            when 'approved' then 'Solicitud aprobada'
            when 'converted' then 'Registro completado'
            when 'waitlist' then 'En lista de espera'
            when 'rejected' then 'Solicitud no aprobada'
            else 'Solicitud recibida'
        end,
        case v_application.status
            when 'pending_delivery' then 'Estamos confirmando la recepción de tu solicitud.'
            when 'delivery_failed' then 'El equipo debe verificar manualmente la recepción.'
            when 'received' then 'El equipo Higo realizará la revisión inicial y te indicará el siguiente paso.'
            when 'under_review' then 'Estamos validando cobertura, datos y capacidad operativa.'
            when 'documents_requested' then 'Revisa tu correo y completa la carga segura de requisitos.'
            when 'documents_submitted' then 'Tus documentos fueron recibidos y están pendientes de revisión.'
            when 'correction_requested' then 'Revisa el correo del equipo Higo y corrige los documentos indicados.'
            when 'approved' then 'Tu solicitud fue aprobada. El equipo completará la creación de tu cuenta.'
            when 'converted' then 'Tu cuenta Higo Driver fue creada. Revisa tu correo para ingresar.'
            when 'waitlist' then 'Tu zona o modalidad está temporalmente sin cupo.'
            when 'rejected' then 'La solicitud no cumple actualmente los criterios de incorporación.'
            else 'El equipo Higo revisará tu solicitud.'
        end
      into v_label, v_next_step;

    return jsonb_build_object(
        'application_id', v_application.application_code,
        'status', v_application.status,
        'status_label', v_label,
        'next_step', v_next_step,
        'updated_at', v_application.updated_at
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_quote_ride_v2(p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_stops_count integer DEFAULT 0, p_promo_code text DEFAULT NULL::text, p_user_id uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_type text := public.higo_canonical_vehicle_type(p_vehicle_type);
    v_base numeric := 0;
    v_per_km numeric := 0;
    v_delivery_fee numeric := 0;
    v_stop_fee numeric := 0;
    v_haversine numeric;
    v_distance numeric;
    v_surge numeric := 1;
    v_subtotal numeric;
    v_discount numeric := 0;
    v_final numeric;
    v_promo record;
    v_promo_id bigint := null;
    v_resolved_promo_code text := null;
    v_promo_valid boolean := false;
    v_promo_error text := null;
    v_user_uses bigint := 0;
    v_stops integer := greatest(0, least(coalesce(p_stops_count, 0), 5));
begin
    if p_pickup_lat is null or p_pickup_lng is null
       or p_dropoff_lat is null or p_dropoff_lng is null then
        raise exception 'ride_coordinates_required';
    end if;

    select
        pc.base,
        pc.per_km,
        pc.delivery_fee,
        pc.stop_fee
    into v_base, v_per_km, v_delivery_fee, v_stop_fee
    from public.pricing_config pc
    where public.higo_canonical_vehicle_type(pc.vehicle_type) = v_type
    limit 1;

    if v_base is null then
        if v_type = 'moto' then
            v_base := 1.00;
            v_per_km := 0.25;
            v_delivery_fee := 0.50;
            v_stop_fee := 0.50;
        elsif v_type = 'van' then
            v_base := 1.70;
            v_per_km := 0.60;
            v_delivery_fee := 2.00;
            v_stop_fee := 1.00;
        else
            v_base := 1.50;
            v_per_km := 0.40;
            v_delivery_fee := 1.50;
            v_stop_fee := 1.00;
        end if;
    end if;

    v_haversine := public.higo_haversine_km(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng
    );

    v_distance := greatest(
        v_haversine,
        least(
            coalesce(p_route_distance_km, v_haversine),
            greatest(v_haversine * 4, v_haversine + 5)
        )
    );

    begin
        execute 'select public.get_active_pricing_multiplier($1,$2::numeric,$3::numeric)'
        into v_surge
        using v_type, p_pickup_lat, p_pickup_lng;
    exception
        when undefined_function then
            v_surge := 1;
        when others then
            v_surge := 1;
    end;
    v_surge := greatest(1, least(coalesce(v_surge, 1), 5));

    v_subtotal := (
        v_base
        + greatest(0, v_distance - 1) * v_per_km
        + v_stops * coalesce(v_stop_fee, 0)
        + case
            when coalesce(p_service_type, 'ride') = 'delivery'
                then coalesce(v_delivery_fee, 0)
            else 0
          end
    ) * v_surge;
    v_subtotal := round(greatest(v_base, v_subtotal), 2);

    if coalesce(trim(p_promo_code), '') <> '' then
        select
            pc.id,
            pc.code,
            pc.discount_type,
            pc.discount_value,
            pc.min_ride_amount,
            pc.expires_at,
            pc.max_uses,
            pc.max_uses_per_user,
            pc.used_count,
            pc.active,
            pc.archived_at,
            pc.budget_amount,
            pc.spent_amount
        into v_promo
        from public.promo_codes pc
        where upper(pc.code) = upper(trim(p_promo_code))
        limit 1;

        if not found then
            v_promo_error := 'inactive';
        else
            v_promo_id := v_promo.id;
            v_resolved_promo_code := v_promo.code;

            if not coalesce(v_promo.active, false)
               or v_promo.archived_at is not null then
                v_promo_error := 'inactive';
            elsif v_promo.expires_at is not null
                  and v_promo.expires_at < now() then
                v_promo_error := 'expired';
            elsif v_subtotal < coalesce(v_promo.min_ride_amount, 0) then
                v_promo_error := 'minimum_not_met';
            elsif v_promo.max_uses is not null
                  and coalesce(v_promo.used_count, 0) >= v_promo.max_uses then
                v_promo_error := 'usage_limit_reached';
            else
                if p_user_id is not null
                   and v_promo.max_uses_per_user is not null then
                    select count(*)
                    into v_user_uses
                    from public.promo_redemptions pr
                    where pr.promo_id = v_promo_id
                      and pr.user_id = p_user_id;
                end if;

                if v_promo.max_uses_per_user is not null
                   and v_user_uses >= v_promo.max_uses_per_user then
                    v_promo_error := 'user_limit_reached';
                else
                    v_discount := case
                        when v_promo.discount_type = 'percent'
                            then v_subtotal * coalesce(v_promo.discount_value, 0) / 100
                        else least(coalesce(v_promo.discount_value, 0), v_subtotal)
                    end;
                    v_discount := round(
                        greatest(0, least(v_discount, v_subtotal)),
                        2
                    );

                    if v_promo.budget_amount is not null
                       and coalesce(v_promo.spent_amount, 0) + v_discount
                           > v_promo.budget_amount then
                        v_discount := 0;
                        v_promo_error := 'budget_exhausted';
                    else
                        v_promo_valid := true;
                    end if;
                end if;
            end if;
        end if;
    end if;

    v_final := round(greatest(0, v_subtotal - v_discount), 2);

    return jsonb_build_object(
        'vehicleType', v_type,
        'serviceType', coalesce(p_service_type, 'ride'),
        'distanceKm', round(v_distance, 3),
        'haversineKm', round(v_haversine, 3),
        'stopsCount', v_stops,
        'base', v_base,
        'perKm', v_per_km,
        'deliveryFee', case
            when p_service_type = 'delivery' then v_delivery_fee
            else 0
        end,
        'stopFee', v_stop_fee,
        'surgeMultiplier', v_surge,
        'subtotal', v_subtotal,
        'discount', v_discount,
        'finalPrice', v_final,
        'promoId', case when v_promo_valid then v_promo_id else null end,
        'promoCode', case
            when v_promo_valid then v_resolved_promo_code
            else null
        end,
        'promoValid', v_promo_valid,
        'promoError', v_promo_error,
        'generatedAt', now()
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_quote_ride_v3(p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_stops_count integer DEFAULT 0, p_promo_code text DEFAULT NULL::text, p_user_id uuid DEFAULT auth.uid(), p_client_subtotal_floor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_quote jsonb;
    v_subtotal numeric;
    v_discount numeric := 0;
    v_final numeric;
    v_floor numeric := greatest(0, coalesce(p_client_subtotal_floor, 0));
    v_promo record;
begin
    v_quote := public.higo_quote_ride_v2(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        p_vehicle_type,
        p_service_type,
        p_route_distance_km,
        p_stops_count,
        p_promo_code,
        p_user_id
    );

    v_subtotal := greatest(coalesce((v_quote->>'subtotal')::numeric, 0), v_floor);

    if coalesce((v_quote->>'promoValid')::boolean, false) then
        select
            pc.id,
            pc.discount_type,
            pc.discount_value,
            pc.budget_amount,
            pc.spent_amount
        into v_promo
        from public.promo_codes pc
        where pc.id = (v_quote->>'promoId')::bigint;

        v_discount := case
            when v_promo.discount_type = 'percent'
                then v_subtotal * coalesce(v_promo.discount_value, 0) / 100
            else least(coalesce(v_promo.discount_value, 0), v_subtotal)
        end;
        v_discount := round(greatest(0, least(v_discount, v_subtotal)), 2);

        if v_promo.budget_amount is not null
           and coalesce(v_promo.spent_amount, 0) + v_discount > v_promo.budget_amount then
            return v_quote || jsonb_build_object(
                'subtotal', v_subtotal,
                'discount', 0,
                'finalPrice', v_subtotal,
                'promoValid', false,
                'promoError', 'budget_exhausted',
                'clientSubtotalFloor', v_floor,
                'clientSubtotalFloorApplied', v_floor > coalesce((v_quote->>'subtotal')::numeric, 0)
            );
        end if;

        v_quote := v_quote || jsonb_build_object(
            'promoDiscountType', v_promo.discount_type,
            'promoDiscountValue', v_promo.discount_value
        );
    end if;

    v_final := round(greatest(0, v_subtotal - v_discount), 2);
    return v_quote || jsonb_build_object(
        'subtotal', v_subtotal,
        'discount', v_discount,
        'finalPrice', v_final,
        'clientSubtotalFloor', v_floor,
        'clientSubtotalFloorApplied', v_floor > coalesce((v_quote->>'subtotal')::numeric, 0)
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_quote_ride_v4(p_pickup_lat double precision, p_pickup_lng double precision, p_dropoff_lat double precision, p_dropoff_lng double precision, p_vehicle_type text, p_service_type text DEFAULT 'ride'::text, p_route_distance_km numeric DEFAULT NULL::numeric, p_route_duration_min numeric DEFAULT NULL::numeric, p_stops_count integer DEFAULT 0, p_promo_code text DEFAULT NULL::text, p_user_id uuid DEFAULT auth.uid(), p_client_subtotal_floor numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_type text := public.higo_canonical_vehicle_type(p_vehicle_type);
    v_legacy jsonb;
    v_result jsonb;
    v_base numeric;
    v_per_km numeric;
    v_per_minute numeric;
    v_delivery_fee numeric;
    v_stop_fee numeric;
    v_minimum_fare numeric;
    v_included_km numeric;
    v_vehicle_max numeric;
    v_pricing_version integer;
    v_distance numeric;
    v_duration numeric;
    v_distance_amount numeric;
    v_time_amount numeric;
    v_stops_amount numeric;
    v_extras_amount numeric;
    v_pre_multiplier numeric;
    v_multiplier numeric;
    v_multiplier_reason text;
    v_legacy_subtotal numeric;
    v_model_subtotal numeric;
    v_charged_subtotal numeric;
    v_mode text := 'shadow';
    v_pilot_percentage numeric := 0;
    v_rollout_max numeric := 1.30;
    v_bucket integer := public.higo_pricing_bucket(p_user_id);
    v_model_applied boolean := false;
    v_stops integer := greatest(0, least(coalesce(p_stops_count, 0), 5));
    v_duration_cap numeric;
begin
    -- Cotización legada sin promoción: fuente segura para distancia, surge y
    -- piso de compatibilidad con clientes existentes.
    v_legacy := public.higo_quote_ride_v3(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        v_type,
        p_service_type,
        p_route_distance_km,
        v_stops,
        null,
        p_user_id,
        null
    );

    select
        coalesce(pc.base, 0),
        coalesce(pc.per_km, 0),
        coalesce(pc.per_minute, 0),
        coalesce(pc.delivery_fee, 0),
        coalesce(pc.stop_fee, 0),
        greatest(coalesce(pc.minimum_fare, pc.base, 0), coalesce(pc.base, 0)),
        greatest(0, coalesce(pc.included_km, 1)),
        greatest(1, coalesce(pc.maximum_multiplier, 1.30)),
        coalesce(pc.pricing_version, 4)
    into
        v_base, v_per_km, v_per_minute, v_delivery_fee, v_stop_fee,
        v_minimum_fare, v_included_km, v_vehicle_max, v_pricing_version
    from public.pricing_config pc
    where public.higo_canonical_vehicle_type(pc.vehicle_type) = v_type
    limit 1;

    if v_base is null then
        if v_type = 'moto' then
            v_base := 1.00; v_per_km := 0.25; v_delivery_fee := 0.50; v_stop_fee := 0.50;
        elsif v_type = 'van' then
            v_base := 1.70; v_per_km := 0.60; v_delivery_fee := 2.00; v_stop_fee := 1.00;
        else
            v_base := 1.50; v_per_km := 0.40; v_delivery_fee := 1.50; v_stop_fee := 1.00;
        end if;
        v_per_minute := 0;
        v_minimum_fare := v_base;
        v_included_km := 1;
        v_vehicle_max := 1.30;
        v_pricing_version := 4;
    end if;

    select mode, pilot_percentage, maximum_multiplier
    into v_mode, v_pilot_percentage, v_rollout_max
    from public.pricing_rollout_config
    where id = 1;

    v_mode := coalesce(v_mode, 'shadow');
    v_pilot_percentage := greatest(0, least(coalesce(v_pilot_percentage, 0), 100));
    v_rollout_max := greatest(1, least(coalesce(v_rollout_max, 1.30), 3));

    v_distance := greatest(0, coalesce((v_legacy->>'distanceKm')::numeric, 0));

    -- El tiempo lo entrega el proveedor de rutas. Se limita para impedir que un
    -- cliente manipulado infle la cotización: máximo 30 min fijos + 12 min/km.
    v_duration_cap := greatest(30, v_distance * 12 + 30);
    v_duration := greatest(0, least(coalesce(p_route_duration_min, 0), v_duration_cap));

    v_multiplier := greatest(
        1,
        least(
            coalesce((v_legacy->>'surgeMultiplier')::numeric, 1),
            v_vehicle_max,
            v_rollout_max
        )
    );
    v_multiplier_reason := case when v_multiplier > 1 then 'regla_zona_horario' else 'tarifa_normal' end;

    v_distance_amount := round(greatest(0, v_distance - v_included_km) * v_per_km, 2);
    v_time_amount := round(v_duration * v_per_minute, 2);
    v_stops_amount := round(v_stops * v_stop_fee, 2);
    v_extras_amount := round(
        case when coalesce(p_service_type, 'ride') = 'delivery' then v_delivery_fee else 0 end,
        2
    );
    v_pre_multiplier := v_base + v_distance_amount + v_time_amount + v_stops_amount + v_extras_amount;
    v_model_subtotal := round(greatest(v_minimum_fare, v_pre_multiplier * v_multiplier), 2);
    v_legacy_subtotal := round(greatest(0, coalesce((v_legacy->>'subtotal')::numeric, 0)), 2);

    v_model_applied := case
        when v_mode = 'active' then true
        when v_mode = 'pilot' then v_bucket < v_pilot_percentage
        else false
    end;

    v_charged_subtotal := greatest(
        v_legacy_subtotal,
        case when v_model_applied then v_model_subtotal else v_legacy_subtotal end,
        greatest(0, coalesce(p_client_subtotal_floor, 0))
    );

    -- Reutiliza toda la validación transaccional de promociones de V3, pero
    -- usando el subtotal elegido por el rollout como piso no reducible.
    v_result := public.higo_quote_ride_v3(
        p_pickup_lat,
        p_pickup_lng,
        p_dropoff_lat,
        p_dropoff_lng,
        v_type,
        p_service_type,
        p_route_distance_km,
        v_stops,
        p_promo_code,
        p_user_id,
        v_charged_subtotal
    );

    return v_result || jsonb_build_object(
        'pricingVersion', v_pricing_version,
        'pricingModel', 'distance_time_minimum_v4',
        'rolloutMode', v_mode,
        'modelApplied', v_model_applied,
        'pilotBucket', v_bucket,
        'distanceKm', round(v_distance, 3),
        'durationMin', round(v_duration, 2),
        'durationCapped', coalesce(p_route_duration_min, 0) > v_duration,
        'base', round(v_base, 2),
        'perKm', v_per_km,
        'perMinute', v_per_minute,
        'includedKm', v_included_km,
        'minimumFare', round(v_minimum_fare, 2),
        'maximumMultiplier', least(v_vehicle_max, v_rollout_max),
        'distanceAmount', v_distance_amount,
        'timeAmount', v_time_amount,
        'stopsAmount', v_stops_amount,
        'extrasAmount', v_extras_amount,
        'surgeMultiplier', v_multiplier,
        'multiplierReason', v_multiplier_reason,
        'legacySubtotal', v_legacy_subtotal,
        'modelSubtotal', v_model_subtotal,
        'chargedSubtotal', round(v_charged_subtotal, 2),
        'generatedAt', now()
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_rank_dispatch_candidates(p_ride_id bigint, p_radius_km numeric, p_fairness_multiplier numeric DEFAULT 1)
 RETURNS TABLE(driver_id uuid, distance_km numeric, score numeric, distance_score numeric, wait_score numeric, trip_deficit_score numeric, offer_deficit_score numeric, freshness_score numeric, penalty_score numeric, available_since timestamp with time zone, completed_rides_7d integer, offers_received_24h integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with target_ride as (
    select r.*
    from public.rides r
    where r.id = p_ride_id
      and r.status = 'requested'
      and r.driver_id is null
),
base as (
    select
        p.id as driver_id,
        public.higo_haversine_km(
            p.curr_lat::double precision,
            p.curr_lng::double precision,
            r.pickup_lat::double precision,
            r.pickup_lng::double precision
        )::numeric as distance_km,
        extract(epoch from (now() - coalesce(p.last_location_update, p.updated_at))) / 60
            as location_age_minutes,
        coalesce(ds.available_since, p.last_location_update, p.updated_at, now())
            as available_since
    from target_ride r
    join public.profiles p on true
    left join public.driver_dispatch_state ds on ds.driver_id = p.id
    where p.role = 'driver'
      and p.status = 'online'
      and p.archived_at is null
      and p.suspended_at is null
      and p.curr_lat is not null
      and p.curr_lng is not null
      and coalesce(p.last_location_update, p.updated_at) >= now() - interval '3 minutes'
      and public.higo_canonical_vehicle_type(p.vehicle_type)
          = public.higo_canonical_vehicle_type(r.ride_type)
      and public.higo_haversine_km(
            p.curr_lat::double precision,
            p.curr_lng::double precision,
            r.pickup_lat::double precision,
            r.pickup_lng::double precision
          ) <= greatest(0.5, least(coalesce(p_radius_km, 10), 30))
      and not exists (
          select 1
          from public.rides active_ride
          where active_ride.driver_id = p.id
            and active_ride.status in ('accepted','in_progress','arrived_at_dropoff')
      )
      and not exists (
          select 1
          from public.ride_offers previous_offer
          where previous_offer.ride_id = r.id
            and previous_offer.driver_id = p.id
      )
      and (
          exists (
              select 1
              from public.driver_memberships dm
              where dm.driver_id = p.id
                and dm.voided_at is null
                and dm.status = 'active'
                and dm.expires_at >= now()
          )
          or (
              p.subscription_override_until is not null
              and p.subscription_override_until >= now()
          )
      )
),
metrics as (
    select
        b.*,
        coalesce(ride_stats.completed_7d, 0)::integer as completed_7d,
        coalesce(offer_stats.offers_24h, 0)::integer as offers_24h,
        coalesce(offer_stats.ignored_2h, 0)::integer as ignored_2h,
        coalesce(offer_stats.ignored_30m, 0)::integer as ignored_30m
    from base b
    left join lateral (
        select count(*) filter (
            where coalesce(r.completed_at, r.created_at) >= now() - interval '7 days'
        ) as completed_7d
        from public.rides r
        where r.driver_id = b.driver_id
          and r.status = 'completed'
          and coalesce(r.completed_at, r.created_at) >= now() - interval '7 days'
    ) ride_stats on true
    left join lateral (
        select
            count(*) filter (where o.offered_at >= now() - interval '24 hours') as offers_24h,
            count(*) filter (
                where o.offered_at >= now() - interval '2 hours'
                  and o.status = 'expired'
            ) as ignored_2h,
            count(*) filter (
                where o.offered_at >= now() - interval '30 minutes'
                  and o.status = 'expired'
            ) as ignored_30m
        from public.ride_offers o
        where o.driver_id = b.driver_id
          and o.offered_at >= now() - interval '24 hours'
    ) offer_stats on true
),
eligible as (
    select *
    from metrics
    where ignored_30m < 5
),
bounds as (
    select
        e.*,
        greatest(max(e.completed_7d) over (), 1) as max_completed_7d,
        greatest(max(e.offers_24h) over (), 1) as max_offers_24h
    from eligible e
),
components as (
    select
        b.*,
        greatest(0, 40 * (1 - least(b.distance_km, p_radius_km) / greatest(p_radius_km, 0.5)))
            as c_distance,
        least(30, greatest(0,
            extract(epoch from (now() - b.available_since)) / 60 / 120 * 30
        )) as c_wait,
        greatest(0, 15 * (1 - b.completed_7d::numeric / b.max_completed_7d::numeric))
            as c_trip,
        greatest(0, 10 * (1 - b.offers_24h::numeric / b.max_offers_24h::numeric))
            as c_offer,
        greatest(0, 5 * (1 - least(b.location_age_minutes, 3) / 3))
            as c_fresh,
        least(10, b.ignored_2h * 2)::numeric as c_penalty
    from bounds b
)
select
    c.driver_id,
    round(c.distance_km, 3),
    round((
        c.c_distance
        + greatest(0, coalesce(p_fairness_multiplier, 1))
            * (c.c_wait + c.c_trip + c.c_offer)
        + c.c_fresh
        - c.c_penalty
    )::numeric, 4) as score,
    round(c.c_distance::numeric, 4),
    round(c.c_wait::numeric, 4),
    round(c.c_trip::numeric, 4),
    round(c.c_offer::numeric, 4),
    round(c.c_fresh::numeric, 4),
    round(c.c_penalty::numeric, 4),
    c.available_since,
    c.completed_7d,
    c.offers_24h
from components c
order by score desc, c.distance_km, c.available_since, c.driver_id;
$function$;

CREATE OR REPLACE FUNCTION public.higo_release_driver_application_upload_token(p_token_hash text, p_claim_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_count integer;
begin
    update public.driver_application_upload_tokens
       set claim_id = null,
           claimed_at = null
     where token_hash = p_token_hash
       and claim_id = p_claim_id
       and used_at is null;
    get diagnostics v_count = row_count;
    return v_count = 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_start_progressive_dispatch(p_ride_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_created integer := 0;
    v_first_limit integer;
    v_next_delay integer;
begin
    insert into public.ride_dispatches(
        ride_id, status, current_wave, started_at, next_wave_at,
        dispatch_deadline_at, offers_created, updated_at
    )
    select
        r.id, 'active', 0, now(), now(),
        now() + interval '3 minutes', 0, now()
    from public.rides r
    where r.id = p_ride_id
      and r.status = 'requested'
      and r.driver_id is null
    on conflict (ride_id) do update
    set status = case
            when public.ride_dispatches.status in ('accepted','cancelled','completed')
                then public.ride_dispatches.status
            else 'active'
        end,
        updated_at = now();

    if not found then
        return 0;
    end if;

    v_created := public.higo_dispatch_wave(p_ride_id, 1);

    select add_limit into v_first_limit
    from public.fair_dispatch_wave_config
    where wave_number = 1 and enabled;

    select delay_seconds into v_next_delay
    from public.fair_dispatch_wave_config
    where wave_number = 2 and enabled;

    update public.ride_dispatches
    set next_wave_at = case
            when v_next_delay is null then null
            when v_created < coalesce(v_first_limit, 1) then now()
            else started_at + make_interval(secs => v_next_delay)
        end,
        status = case when v_next_delay is null then 'exhausted' else status end,
        updated_at = now()
    where ride_id = p_ride_id and status = 'active';

    return v_created;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_sync_driver_dispatch_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status = 'completed'
       and old.status is distinct from new.status
       and new.driver_id is not null then
        insert into public.driver_dispatch_state(
            driver_id, is_online, available_since, last_completed_ride_at, updated_at
        )
        select
            new.driver_id,
            p.status = 'online',
            case when p.status = 'online' then now() else null end,
            coalesce(new.completed_at, now()),
            now()
        from public.profiles p
        where p.id = new.driver_id
        on conflict (driver_id) do update
        set is_online = excluded.is_online,
            available_since = excluded.available_since,
            last_completed_ride_at = excluded.last_completed_ride_at,
            updated_at = now();
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_sync_driver_dispatch_presence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.role <> 'driver' then
        return new;
    end if;

    insert into public.driver_dispatch_state(
        driver_id, is_online, available_since, updated_at
    ) values (
        new.id,
        new.status = 'online',
        case when new.status = 'online' then now() else null end,
        now()
    )
    on conflict (driver_id) do update
    set is_online = excluded.is_online,
        available_since = case
            when excluded.is_online and not driver_dispatch_state.is_online then now()
            when excluded.is_online then coalesce(driver_dispatch_state.available_since, now())
            else null
        end,
        updated_at = now();

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_sync_driver_membership(p_driver_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_active boolean := false;
    v_last_payment timestamptz;
    v_pending_suspension boolean := false;
begin
    select
        exists(
            select 1
            from public.driver_memberships dm
            where dm.driver_id = p_driver_id
              and dm.voided_at is null
              and dm.status = 'active'
              and dm.expires_at >= now()
        ),
        max(dm.paid_at) filter (where dm.voided_at is null)
    into v_active, v_last_payment
    from public.driver_memberships dm
    where dm.driver_id = p_driver_id;

    select coalesce(p.suspension_reason, '') in (
        'pending_membership',
        'Alta administrativa pendiente de registrar membresía',
        'membership_expired',
        'Membresía vencida'
    )
    into v_pending_suspension
    from public.profiles p
    where p.id = p_driver_id;

    update public.profiles
    set subscription_status = case when v_active then 'active' else 'suspended' end,
        last_payment_date = v_last_payment,
        suspended_at = case
            when v_active and v_pending_suspension then null
            else suspended_at
        end,
        suspension_reason = case
            when v_active and v_pending_suspension then null
            else suspension_reason
        end
    where id = p_driver_id
      and role = 'driver';
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_sync_progressive_dispatch_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status = 'accepted' and new.driver_id is not null then
        update public.ride_dispatches
        set status = 'accepted', next_wave_at = null,
            completed_at = coalesce(completed_at, now()), updated_at = now()
        where ride_id = new.id and status = 'active';
    elsif new.status = 'cancelled' then
        update public.ride_dispatches
        set status = 'cancelled', next_wave_at = null,
            completed_at = coalesce(completed_at, now()), updated_at = now()
        where ride_id = new.id and status in ('active','exhausted');
    elsif new.status = 'completed' then
        update public.ride_dispatches
        set status = 'completed', next_wave_at = null,
            completed_at = coalesce(completed_at, now()), updated_at = now()
        where ride_id = new.id;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_sync_ride_offer_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status = 'accepted' and new.driver_id is not null then
        update public.ride_offers
        set status = case when driver_id = new.driver_id then 'accepted' else 'withdrawn' end,
            responded_at = case when driver_id = new.driver_id then now() else responded_at end
        where ride_id = new.id
          and status = 'offered';
    elsif new.status in ('cancelled','completed') then
        update public.ride_offers
        set status = case when status = 'accepted' then status else 'withdrawn' end
        where ride_id = new.id
          and status = 'offered';
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.higo_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at := now();
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_admin(p_uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = p_uid AND role = 'admin'
    );
$function$;

CREATE OR REPLACE FUNCTION public.is_driver(p_uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = p_uid AND role = 'driver'
    );
$function$;

CREATE OR REPLACE FUNCTION public.is_within_coverage(p_lat double precision, p_lng double precision)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.coverage_zones
        WHERE active = TRUE
          AND 2 * 6371 * asin(sqrt(
              power(sin(radians((center_lat - p_lat) / 2)), 2)
              + cos(radians(p_lat)) * cos(radians(center_lat))
              * power(sin(radians((center_lng - p_lng) / 2)), 2)
          )) <= radius_km
    );
$function$;

CREATE OR REPLACE FUNCTION public.mark_support_thread_read(p_thread_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    my_id         UUID;
    is_admin      BOOLEAN;
    is_owner      BOOLEAN;
    role_to_mark  TEXT;
BEGIN
    my_id := auth.uid();
    IF my_id IS NULL THEN RETURN; END IF;

    SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = my_id AND p.role = 'admin') INTO is_admin;
    SELECT EXISTS (SELECT 1 FROM public.support_threads t WHERE t.id = p_thread_id AND t.user_id = my_id) INTO is_owner;

    IF NOT (is_admin OR is_owner) THEN RETURN; END IF;

    -- El admin marca como leídos los mensajes del user, y viceversa.
    role_to_mark := CASE WHEN is_admin THEN 'user' ELSE 'admin' END;

    UPDATE public.support_messages
       SET read_at = timezone('utc', now())
     WHERE thread_id = p_thread_id
       AND sender_role = role_to_mark
       AND read_at IS NULL;

    UPDATE public.support_threads
       SET unread_for_admin = CASE WHEN is_admin THEN false ELSE unread_for_admin END,
           unread_for_user  = CASE WHEN is_owner THEN false ELSE unread_for_user  END
     WHERE id = p_thread_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.passenger_cancel_ride_v2(p_ride_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_from text;
    v_result jsonb;
begin
    if coalesce(trim(p_reason), '') = '' then raise exception 'cancellation_reason_required'; end if;

    select r.status into v_from
    from public.rides r
    where r.id = p_ride_id
      and r.user_id = auth.uid()
    for update;

    if v_from is null then raise exception 'ride_not_found'; end if;
    if v_from = 'cancelled' then
        select to_jsonb(r) into v_result from public.rides r where r.id = p_ride_id;
        return v_result;
    end if;
    if v_from not in ('requested','accepted') then raise exception 'ride_cannot_be_cancelled'; end if;

    update public.rides r
    set status = 'cancelled',
        cancellation_reason = trim(p_reason),
        cancelled_at = coalesce(r.cancelled_at, now())
    where r.id = p_ride_id
    returning to_jsonb(r) into v_result;

    perform public.higo_log_ride_event(
        p_ride_id, v_from, 'cancelled', 'passenger.cancel',
        jsonb_build_object('reason', trim(p_reason))
    );
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.profiles_sensitive_unchanged(p_role text, p_sub text, p_lastpay timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles
         WHERE id = auth.uid()
           AND role                IS NOT DISTINCT FROM p_role
           AND subscription_status IS NOT DISTINCT FROM p_sub
           AND last_payment_date   IS NOT DISTINCT FROM p_lastpay
    );
$function$;

CREATE OR REPLACE FUNCTION public.refresh_fraud_signals()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NOT public.is_admin(auth.uid()) THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    REFRESH MATERIALIZED VIEW public.fraud_signals;
    RETURN NOW();
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_membership_payment(p_bank_origin text, p_reference_last6 text, p_sender_phone text, p_amount_reported numeric, p_amount_real numeric, p_trn_date date, p_banesco_status text, p_raw_response jsonb, p_driver_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_driver        UUID := COALESCE(auth.uid(), p_driver_id);
    v_plan          TEXT;
    v_period        TEXT;
    v_plan_bs       NUMERIC;
    v_membership_id BIGINT;
    v_report_id     BIGINT;
    v_expires       TIMESTAMPTZ;
BEGIN
    IF v_driver IS NULL THEN
        RAISE EXCEPTION 'no auth' USING ERRCODE = '28000';
    END IF;

    IF p_amount_real IS NULL OR p_amount_real <= 0 THEN
        RAISE EXCEPTION 'amount_real inválido' USING ERRCODE = '22023';
    END IF;

    SELECT CASE
               WHEN COALESCE(NULLIF(vehicle_model,''), '') IN ('moto','standard','van')
               THEN vehicle_model
               ELSE 'standard'
           END
      INTO v_plan
      FROM public.profiles
     WHERE id = v_driver;

    SELECT period, amount_bs
      INTO v_period, v_plan_bs
      FROM public.membership_plans
     WHERE plan = v_plan;
    IF v_period IS NULL THEN v_period := 'monthly'; END IF;

    -- Defensa de monto (mig 17): si hay precio de referencia en BS, exigir
    -- al menos 95%. banesco-validate.php ya compara contra la tasa BCV viva.
    IF v_plan_bs IS NOT NULL AND v_plan_bs > 0
       AND p_amount_real < v_plan_bs * 0.95 THEN
        RAISE EXCEPTION 'monto insuficiente: % Bs < % Bs (95%% de %)',
                        p_amount_real, v_plan_bs * 0.95, v_plan_bs
              USING ERRCODE = '22023';
    END IF;

    v_expires := CASE v_period
        WHEN 'weekly'  THEN NOW() + INTERVAL '7 days'
        WHEN 'monthly' THEN NOW() + INTERVAL '30 days'
        WHEN 'yearly'  THEN NOW() + INTERVAL '365 days'
    END;

    INSERT INTO public.driver_memberships
        (driver_id, plan, amount, period, payment_method, reference, paid_at, expires_at, status)
    VALUES
        (v_driver, v_plan, p_amount_real, v_period, 'banesco',
         p_reference_last6, NOW(), v_expires, 'active')
    RETURNING id INTO v_membership_id;

    INSERT INTO public.payment_reports
        (driver_id, bank_origin, reference_last6, sender_phone,
         amount_reported, amount_real, trn_date,
         banesco_status, status, membership_id, raw_response)
    VALUES
        (v_driver, p_bank_origin, p_reference_last6, p_sender_phone,
         p_amount_reported, p_amount_real, p_trn_date,
         p_banesco_status, 'validated', v_membership_id, p_raw_response)
    RETURNING id INTO v_report_id;

    RETURN jsonb_build_object(
        'membership_id', v_membership_id,
        'report_id',     v_report_id,
        'expires_at',    v_expires
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_membership_payment_core(p_driver_id uuid, p_plan_id uuid, p_payment_type text, p_bank_origin text, p_reference text, p_sender_phone text, p_amount_reported numeric, p_amount_real numeric, p_trn_date date, p_banesco_status text, p_raw_response jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_plan public.driver_membership_plans%rowtype;
    v_vehicle_type text;
    v_report_id text;
    v_membership_id bigint;
    v_start timestamptz;
    v_expires timestamptz;
begin
    select * into v_plan
    from public.driver_membership_plans
    where id = p_plan_id
      and active
    for share;

    if not found then
        raise exception 'membership_plan_not_found';
    end if;

    select public.higo_canonical_vehicle_type(
        coalesce(nullif(p.vehicle_type, ''), nullif(p.vehicle_model, ''), 'standard')
    )
    into v_vehicle_type
    from public.profiles p
    where p.id = p_driver_id
      and p.role = 'driver'
      and p.archived_at is null
    for update;

    if v_vehicle_type is null then
        raise exception 'driver_not_found_or_archived';
    end if;

    if public.higo_canonical_vehicle_type(v_plan.vehicle_type) <> v_vehicle_type then
        raise exception 'membership_plan_vehicle_mismatch';
    end if;

    if coalesce(trim(p_reference), '') = '' then
        raise exception 'payment_reference_required';
    end if;

    begin
        insert into public.payment_reports(
            driver_id,
            payment_type,
            bank_origin,
            reference_last6,
            sender_phone,
            amount_reported,
            amount_real,
            trn_date,
            banesco_status,
            status,
            raw_response,
            membership_plan_id,
            membership_plan_code
        ) values (
            p_driver_id,
            p_payment_type,
            p_bank_origin,
            trim(p_reference),
            nullif(trim(p_sender_phone), ''),
            p_amount_reported,
            p_amount_real,
            p_trn_date,
            p_banesco_status,
            'validated',
            coalesce(p_raw_response, '{}'::jsonb),
            v_plan.id,
            v_plan.code
        )
        returning id::text into v_report_id;
    exception
        when unique_violation then
            raise exception 'payment_reference_already_used' using errcode = '23505';
    end;

    select greatest(
        now(),
        coalesce(max(dm.expires_at) filter (
            where dm.voided_at is null
              and dm.status = 'active'
              and dm.expires_at > now()
        ), now())
    )
    into v_start
    from public.driver_memberships dm
    where dm.driver_id = p_driver_id;

    v_expires := v_start + make_interval(days => v_plan.duration_days);

    insert into public.driver_memberships(
        driver_id,
        plan_id,
        plan,
        amount,
        currency,
        period,
        paid_at,
        expires_at,
        status,
        payment_method,
        payment_reference,
        payment_report_id,
        source,
        created_by
    ) values (
        p_driver_id,
        v_plan.id,
        v_plan.code,
        v_plan.amount,
        v_plan.currency,
        v_plan.period,
        now(),
        v_expires,
        'active',
        p_payment_type,
        trim(p_reference),
        v_report_id,
        'banesco',
        p_driver_id
    )
    returning id into v_membership_id;

    update public.profiles
    set subscription_status = 'active',
        last_payment_date = now(),
        suspended_at = null,
        suspension_reason = null
    where id = p_driver_id;

    if to_regclass('public.admin_audit_log') is not null then
        insert into public.admin_audit_log(
            actor_id, action, entity_type, entity_id, after_data, metadata
        ) values (
            p_driver_id,
            'membership.payment_validated',
            'driver_membership',
            v_membership_id::text,
            jsonb_build_object(
                'driver_id', p_driver_id,
                'plan_id', v_plan.id,
                'plan_code', v_plan.code,
                'expires_at', v_expires,
                'payment_report_id', v_report_id
            ),
            jsonb_build_object('source', 'banesco')
        );
    end if;

    return jsonb_build_object(
        'membership_id', v_membership_id,
        'report_id', v_report_id,
        'plan_id', v_plan.id,
        'plan_code', v_plan.code,
        'expires_at', v_expires
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.register_membership_payment_v2(p_driver_id uuid, p_plan_id uuid, p_payment_type text, p_bank_origin text, p_reference text, p_sender_phone text, p_amount_reported numeric, p_amount_real numeric, p_trn_date date, p_banesco_status text, p_raw_response jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select public.register_membership_payment_v3(
        p_driver_id,
        p_plan_id,
        p_payment_type,
        p_bank_origin,
        p_reference,
        p_sender_phone,
        p_amount_reported,
        p_amount_real,
        p_trn_date,
        p_banesco_status,
        p_raw_response
    );
$function$;

CREATE OR REPLACE FUNCTION public.register_membership_payment_v3(p_driver_id uuid, p_plan_id uuid, p_payment_type text, p_bank_origin text, p_reference text, p_sender_phone text, p_amount_reported numeric, p_amount_real numeric, p_trn_date date, p_banesco_status text, p_raw_response jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_original_suspended_at timestamptz;
    v_original_reason text;
    v_membership_suspension boolean := false;
    v_result jsonb;
begin
    select p.suspended_at, p.suspension_reason
    into v_original_suspended_at, v_original_reason
    from public.profiles p
    where p.id = p_driver_id
      and p.role = 'driver'
    for update;

    if not found then
        raise exception 'driver_not_found';
    end if;

    v_membership_suspension := coalesce(v_original_reason, '') in (
        '',
        'pending_membership',
        'Alta administrativa pendiente de registrar membresía',
        'membership_expired',
        'Membresía vencida'
    );

    v_result := public.register_membership_payment_core(
        p_driver_id,
        p_plan_id,
        p_payment_type,
        p_bank_origin,
        p_reference,
        p_sender_phone,
        p_amount_reported,
        p_amount_real,
        p_trn_date,
        p_banesco_status,
        p_raw_response
    );

    if v_original_suspended_at is not null and not v_membership_suspension then
        update public.profiles
        set suspended_at = v_original_suspended_at,
            suspension_reason = v_original_reason,
            subscription_status = 'suspended'
        where id = p_driver_id;

        if to_regclass('public.admin_audit_log') is not null then
            insert into public.admin_audit_log(
                actor_id, action, entity_type, entity_id, after_data, reason, metadata
            ) values (
                p_driver_id,
                'membership.payment_preserved_suspension',
                'profile',
                p_driver_id::text,
                jsonb_build_object(
                    'membership_id', v_result->>'membership_id',
                    'suspended_at', v_original_suspended_at,
                    'suspension_reason', v_original_reason
                ),
                'El pago renovó la membresía pero no levantó una suspensión disciplinaria.',
                jsonb_build_object('source', 'register_membership_payment_v3')
            );
        end if;
    else
        perform public.higo_sync_driver_membership(p_driver_id);
    end if;

    return v_result || jsonb_build_object(
        'operational_suspension_preserved',
        v_original_suspended_at is not null and not v_membership_suspension
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.register_referral(p_code text, p_referred_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_referrer_id UUID;
BEGIN
    SELECT id INTO v_referrer_id FROM public.profiles WHERE referral_code = UPPER(p_code);
    IF v_referrer_id IS NULL THEN
        RETURN jsonb_build_object('ok', FALSE, 'message', 'Código de referido inválido');
    END IF;
    IF v_referrer_id = p_referred_id THEN
        RETURN jsonb_build_object('ok', FALSE, 'message', 'No puedes referirte a ti mismo');
    END IF;

    INSERT INTO public.referrals (referrer_id, referred_id, referral_code)
    VALUES (v_referrer_id, p_referred_id, UPPER(p_code))
    ON CONFLICT (referred_id) DO NOTHING;

    RETURN jsonb_build_object('ok', TRUE, 'referrer_id', v_referrer_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_store_membership_payment(p_store_id uuid, p_bank_origin text, p_reference_last6 text, p_sender_phone text, p_amount_reported numeric, p_amount_real numeric, p_trn_date date, p_banesco_status text, p_raw_response jsonb, p_caller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid             UUID := COALESCE(auth.uid(), p_caller_id);
    v_owner           UUID;
    v_membership_id   BIGINT;
    v_current_expires TIMESTAMPTZ;
    v_expires         TIMESTAMPTZ;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'no auth' USING ERRCODE = '28000';
    END IF;

    SELECT owner_id INTO v_owner FROM public.stores WHERE id = p_store_id;
    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'tienda no encontrada' USING ERRCODE = '42704';
    END IF;

    IF v_owner <> v_uid AND NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = v_uid AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'no autorizado para esta tienda' USING ERRCODE = '42501';
    END IF;

    IF p_amount_real IS NULL OR p_amount_real <= 0 THEN
        RAISE EXCEPTION 'amount_real inválido' USING ERRCODE = '22023';
    END IF;

    SELECT expires_at INTO v_current_expires
    FROM public.store_memberships
    WHERE store_id = p_store_id AND status = 'active' AND expires_at > NOW()
    ORDER BY expires_at DESC
    LIMIT 1;

    IF v_current_expires IS NOT NULL THEN
        v_expires := v_current_expires + INTERVAL '30 days';
    ELSE
        v_expires := NOW() + INTERVAL '30 days';
    END IF;

    INSERT INTO public.store_memberships (
        store_id, amount, payment_method, reference, status, paid_at, expires_at, notes,
        bank_origin, sender_phone, raw_response
    ) VALUES (
        p_store_id, p_amount_real, 'pago_movil', p_reference_last6, 'active', NOW(), v_expires,
        'Pago móvil Banesco validado automáticamente.', p_bank_origin, p_sender_phone, p_raw_response
    )
    RETURNING id INTO v_membership_id;

    RETURN jsonb_build_object(
        'membership_id', v_membership_id,
        'expires_at',    v_expires
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_delivery_claim(p_claim_id uuid, p_admin_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  UPDATE public.delivery_claims
     SET status = 'rejected',
         admin_resolution_note = p_admin_note,
         resolved_by = auth.uid(),
         resolved_at = NOW()
   WHERE id = p_claim_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_delivery_claim_for_claimant(p_claim_id uuid, p_admin_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin_id UUID;
  v_driver_id UUID;
  v_claim_id UUID;
BEGIN
  v_admin_id := auth.uid();
  IF NOT public.is_admin(v_admin_id) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  -- Suspender al chofer y marcar el claim resuelto en una transacción.
  UPDATE public.delivery_claims c
     SET status = 'resolved_for_claimant',
         admin_resolution_note = p_admin_note,
         driver_contact_shared = true,
         driver_contact_shared_at = NOW(),
         resolved_by = v_admin_id,
         resolved_at = NOW()
   WHERE c.id = p_claim_id
   RETURNING (
     SELECT r.driver_id FROM public.rides r WHERE r.id = c.ride_id
   ) INTO v_driver_id;

  IF v_driver_id IS NULL THEN
    RAISE EXCEPTION 'claim_not_found_or_no_driver';
  END IF;

  UPDATE public.profiles
     SET suspended_at = NOW(),
         suspended_reason = 'delivery_claim_' || p_claim_id::text
   WHERE id = v_driver_id
     AND suspended_at IS NULL;

  RETURN v_driver_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.ride_confirm_payment_v2(p_ride_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ride public.rides%rowtype;
    v_role text;
    v_updates jsonb := '{}'::jsonb;
    v_result jsonb;
begin
    select * into v_ride from public.rides r where r.id = p_ride_id for update;
    if not found then raise exception 'ride_not_found'; end if;

    select p.role into v_role from public.profiles p where p.id = auth.uid();
    if auth.uid() = v_ride.driver_id and v_role = 'driver' then
        update public.rides r
        set payment_confirmed_by_driver = true,
            payment_confirmed_at = case when r.payment_confirmed_by_user then coalesce(r.payment_confirmed_at, now()) else r.payment_confirmed_at end
        where r.id = p_ride_id
        returning to_jsonb(r) into v_result;
        v_updates := jsonb_build_object('actor', 'driver');
    elsif auth.uid() = v_ride.user_id then
        update public.rides r
        set payment_confirmed_by_user = true,
            payment_confirmed_at = case when r.payment_confirmed_by_driver then coalesce(r.payment_confirmed_at, now()) else r.payment_confirmed_at end
        where r.id = p_ride_id
        returning to_jsonb(r) into v_result;
        v_updates := jsonb_build_object('actor', 'passenger');
    else
        raise exception 'ride_party_required' using errcode = '42501';
    end if;

    perform public.higo_log_ride_event(
        p_ride_id, v_ride.status, v_ride.status, 'payment.confirm', v_updates
    );
    return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_support_messages(p_query text, p_limit integer DEFAULT 50)
 RETURNS TABLE(message_id bigint, thread_id bigint, content text, sender_role text, created_at timestamp with time zone, thread_status text, thread_role_context text, user_id uuid, user_full_name text, user_role text, user_avatar text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    q TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role = 'admin') THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    q := trim(coalesce(p_query, ''));
    IF length(q) < 2 THEN RETURN; END IF;

    RETURN QUERY
    SELECT m.id, m.thread_id, m.content, m.sender_role, m.created_at,
           t.status, t.role_context, t.user_id, p.full_name, p.role, p.avatar_url
      FROM public.support_messages m
      JOIN public.support_threads t ON t.id = m.thread_id
      LEFT JOIN public.profiles p ON p.id = t.user_id
     WHERE m.deleted_at IS NULL
       AND m.content IS NOT NULL
       AND m.content ILIKE '%' || q || '%'
     ORDER BY m.created_at DESC
     LIMIT GREATEST(1, LEAST(p_limit, 200));
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_delivery_timestamps()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.service_type <> 'delivery' THEN
    RETURN NEW;
  END IF;

  -- accepted → in_progress (chofer recogió el paquete)
  IF NEW.status = 'in_progress' AND OLD.status = 'accepted'
     AND NEW.picked_up_at IS NULL THEN
    NEW.picked_up_at := NOW();
  END IF;

  -- in_progress/picked_up → arrived_at_dropoff (llegó al destino)
  IF NEW.status = 'arrived_at_dropoff'
     AND NEW.arrived_at_dropoff_at IS NULL THEN
    NEW.arrived_at_dropoff_at := NOW();
  END IF;

  -- * → completed (entregado)
  IF NEW.status = 'completed' AND OLD.status <> 'completed'
     AND NEW.delivered_at IS NULL THEN
    NEW.delivered_at := NOW();
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.submit_store_review(p_order_id uuid, p_rating integer, p_comment text DEFAULT NULL::text)
 RETURNS shop_store_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_review public.shop_store_reviews%ROWTYPE;
BEGIN
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'rating debe estar entre 1 y 5';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'orden no encontrada';
  END IF;
  IF v_order.customer_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'solo el cliente de la orden puede calificar';
  END IF;
  IF v_order.status <> 'DELIVERED' THEN
    RAISE EXCEPTION 'solo se pueden calificar órdenes entregadas';
  END IF;
  IF EXISTS (SELECT 1 FROM public.shop_store_reviews WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'esta orden ya fue calificada';
  END IF;

  INSERT INTO public.shop_store_reviews (order_id, store_id, customer_id, rating, comment)
  VALUES (p_order_id, v_order.store_id, auth.uid(), p_rating, nullif(trim(coalesce(p_comment, '')), ''))
  RETURNING * INTO v_review;

  UPDATE public.stores s
  SET rating = sub.avg_rating,
      review_count = sub.review_count,
      updated_at = now()
  FROM (
    SELECT round(avg(rating)::numeric, 2) AS avg_rating, count(*) AS review_count
    FROM public.shop_store_reviews
    WHERE store_id = v_order.store_id
  ) sub
  WHERE s.id = v_order.store_id;

  RETURN v_review;
END;
$function$;

CREATE OR REPLACE FUNCTION public.support_messages_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    preview TEXT;
BEGIN
    preview := CASE
        WHEN NEW.content IS NOT NULL AND length(trim(NEW.content)) > 0
            THEN LEFT(NEW.content, 80)
        WHEN NEW.attachment_path IS NOT NULL
            THEN '📎 Imagen'
        ELSE '(mensaje vacío)'
    END;

    UPDATE public.support_threads
       SET last_message_at      = NEW.created_at,
           last_message_preview = preview,
           unread_for_user      = CASE WHEN NEW.sender_role = 'admin' THEN true  ELSE unread_for_user  END,
           unread_for_admin     = CASE WHEN NEW.sender_role = 'user'  THEN true  ELSE unread_for_admin END
     WHERE id = NEW.thread_id;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.support_stats(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    n_days     INT;
    now_ts     TIMESTAMPTZ;
    cur_start  TIMESTAMPTZ;
    prev_start TIMESTAMPTZ;
    cur        JSONB;
    prev       JSONB;
BEGIN
    -- ▼ Guard nuevo: sesión vencida o request sin token.
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
    END IF;
    -- ▼ Guard preexistente: usuario logueado pero no admin.
    IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role = 'admin') THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;

    n_days     := LEAST(GREATEST(coalesce(p_days, 30), 1), 365);
    now_ts     := timezone('utc', now());
    cur_start  := now_ts - (n_days       || ' days')::INTERVAL;
    prev_start := now_ts - ((n_days * 2) || ' days')::INTERVAL;

    cur  := public._support_stats_window(cur_start,  now_ts);
    prev := public._support_stats_window(prev_start, cur_start);

    RETURN jsonb_build_object(
        'days', n_days,
        'open_count',
            (SELECT count(*) FROM public.support_threads WHERE status = 'open'),
        'open_unanswered',
            (SELECT count(*) FROM public.support_threads WHERE status = 'open' AND unread_for_admin = true),
        'first_response_avg_minutes',    cur->'first_response_avg_minutes',
        'first_response_median_minutes', cur->'first_response_median_minutes',
        'resolution_avg_hours',          cur->'resolution_avg_hours',
        'closed_count',                  cur->'closed_count',
        'volume_by_day',                 cur->'volume_by_day',
        'top_admins',                    cur->'top_admins',
        'previous',                      prev
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_driver_subscription_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    UPDATE public.profiles
       SET subscription_status = CASE
               WHEN public.driver_has_active_membership(NEW.driver_id) THEN 'active'
               ELSE 'suspended'
           END,
           last_payment_date = NEW.paid_at
     WHERE id = NEW.driver_id;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_profile_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if new.curr_lat is not null and new.curr_lng is not null then
    new.location := ST_SetSRID(ST_MakePoint(new.curr_lng, new.curr_lat), 4326)::geography;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_ride_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if new.pickup_lat is not null and new.pickup_lng is not null then
    new.pickup_location := ST_SetSRID(ST_MakePoint(new.pickup_lng, new.pickup_lat), 4326)::geography;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tg_driver_documents_resubmit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.file_path IS DISTINCT FROM OLD.file_path THEN
        NEW.status           := 'pending';
        NEW.submitted_at     := timezone('utc', now());
        NEW.reviewed_at      := NULL;
        NEW.reviewed_by      := NULL;
        NEW.rejection_reason := NULL;
    END IF;
    RETURN NEW;
END;
$function$;

