CREATE OR REPLACE FUNCTION public.track_platform_event(p_event_name text, p_route text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_properties jsonb DEFAULT '{}'::jsonb, p_session_id text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_platform text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id bigint;
    v_properties jsonb := coalesce(p_properties, '{}'::jsonb);
begin
    if coalesce(trim(p_event_name), '') !~ '^[a-z0-9][a-z0-9._-]{1,79}$' then
        raise exception 'invalid_event_name';
    end if;
    if jsonb_typeof(v_properties) <> 'object' then
        raise exception 'event_properties_must_be_object';
    end if;
    if octet_length(v_properties::text) > 8192 then
        raise exception 'event_properties_too_large';
    end if;

    -- Defense in depth: remove known sensitive keys even if a caller sends
    -- them accidentally. Values such as coordinates and bank raw responses
    -- are never useful in the analytics table.
    v_properties := v_properties
        - 'password'
        - 'token'
        - 'access_token'
        - 'refresh_token'
        - 'raw_response'
        - 'pickup_lat'
        - 'pickup_lng'
        - 'dropoff_lat'
        - 'dropoff_lng'
        - 'phone'
        - 'email';

    insert into public.platform_events(
        user_id,
        session_id,
        event_name,
        route,
        entity_type,
        entity_id,
        properties,
        app_version,
        platform
    ) values (
        auth.uid(),
        left(nullif(trim(p_session_id), ''), 100),
        trim(p_event_name),
        left(nullif(trim(p_route), ''), 200),
        left(nullif(trim(p_entity_type), ''), 80),
        left(nullif(trim(p_entity_id), ''), 160),
        v_properties,
        left(nullif(trim(p_app_version), ''), 40),
        left(nullif(trim(p_platform), ''), 80)
    ) returning id into v_id;

    return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_driver_gps(lat double precision, lng double precision, head double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if auth.uid() is null then
        raise exception 'authentication required' using errcode = '42501';
    end if;
    if lat is null or lng is null or lat < -90 or lat > 90 or lng < -180 or lng > 180 then
        raise exception 'invalid driver coordinates' using errcode = '22023';
    end if;

    perform public.higo_assert_driver_operational();

    update public.profiles
    set curr_lat = lat,
        curr_lng = lng,
        heading = coalesce(head, heading),
        last_location_update = now(),
        status = 'online'
    where id = auth.uid()
      and role::text = 'driver';

    if not found then
        raise exception 'driver profile not found' using errcode = '42501';
    end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_cod_collection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.cod_collected = true AND OLD.cod_collected = false THEN
    IF NEW.cod_amount IS NULL OR NEW.cod_amount <= 0 THEN
      RAISE EXCEPTION 'cannot_mark_cod_collected_without_amount';
    END IF;
    IF NEW.cod_collected_at IS NULL THEN
      NEW.cod_collected_at := NOW();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.validate_delivery_category()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cat TEXT;
BEGIN
  IF NEW.service_type <> 'delivery' THEN
    RETURN NEW;
  END IF;

  v_cat := NEW.delivery_info->>'category';

  -- Categoría opcional. Si viene, debe estar en la lista permitida.
  IF v_cat IS NOT NULL AND v_cat NOT IN
     ('normal','fragile','refrigerated','documents','electronics') THEN
    RAISE EXCEPTION 'invalid_delivery_category: %', v_cat;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.validate_delivery_weight()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_weight_bucket TEXT;
  v_max_kg NUMERIC;
  v_weight_kg NUMERIC;
BEGIN
  IF NEW.service_type <> 'delivery' THEN
    RETURN NEW;
  END IF;

  v_weight_bucket := NEW.delivery_info->>'package_weight_kg';
  IF v_weight_bucket IS NULL THEN
    -- Sin peso declarado, lo dejamos pasar (el frontend valida required).
    RETURN NEW;
  END IF;

  -- Map de bucket textual a tope numérico
  v_weight_kg := CASE v_weight_bucket
    WHEN '<1'    THEN 1
    WHEN '1-5'   THEN 5
    WHEN '5-10'  THEN 10
    WHEN '10-25' THEN 25
    WHEN '25-50' THEN 50
    WHEN '>50'   THEN 999
    ELSE NULL
  END;

  IF v_weight_kg IS NULL THEN
    RAISE EXCEPTION 'invalid_weight_bucket: %', v_weight_bucket;
  END IF;

  v_max_kg := CASE NEW.ride_type
    WHEN 'moto'      THEN 5
    WHEN 'standard'  THEN 25
    WHEN 'van'       THEN 50
    WHEN 'camioneta' THEN 50
    ELSE 25
  END;

  IF v_weight_kg > v_max_kg THEN
    RAISE EXCEPTION 'package_too_heavy_for_vehicle: max % kg for %, got bucket %',
      v_max_kg, NEW.ride_type, v_weight_bucket;
  END IF;

  RETURN NEW;
END;
$function$;

