create view public."admin_driver_membership_status" as  SELECT p.id,
    p.full_name,
    p.phone,
    p.email,
    p.avatar_url,
    p.vehicle_type,
    p.vehicle_brand,
    p.vehicle_model,
    p.vehicle_color,
    p.license_plate,
    p.status AS online_status,
    p.updated_at AS location_updated_at,
    p.subscription_status,
    p.last_payment_date,
    p.suspended_at,
    p.suspension_reason,
    p.archived_at,
    p.archive_reason,
    p.subscription_override_until,
    p.created_at,
    m.id AS membership_id,
    m.plan_id,
    COALESCE(mp.name, m.plan) AS membership_plan,
    m.amount AS membership_amount,
    m.currency,
    m.period,
    m.paid_at,
    m.expires_at,
    m.payment_method,
    m.payment_reference,
    higo_membership_status(m.expires_at, m.status, p.archived_at, p.suspended_at, p.subscription_override_until) AS membership_state
   FROM profiles p
     LEFT JOIN LATERAL ( SELECT dm.id,
            dm.driver_id,
            dm.plan,
            dm.amount,
            dm.period,
            dm.payment_method,
            dm.reference,
            dm.paid_at,
            dm.expires_at,
            dm.status,
            dm.notes,
            dm.created_at,
            dm.created_by,
            dm.plan_id,
            dm.currency,
            dm.payment_reference,
            dm.receipt_url,
            dm.voided_at,
            dm.voided_by,
            dm.void_reason,
            dm.updated_at
           FROM driver_memberships dm
          WHERE dm.driver_id = p.id AND dm.voided_at IS NULL
          ORDER BY dm.expires_at DESC, dm.paid_at DESC
         LIMIT 1) m ON true
     LEFT JOIN driver_membership_plans mp ON mp.id = m.plan_id
  WHERE p.role = 'driver'::text;

create materialized view public."fraud_signals" as  SELECT 'passenger'::text AS subject_type,
    r.user_id::text AS subject_id,
    'multiple_cancellations'::text AS signal,
        CASE
            WHEN count(*) FILTER (WHERE r.status = 'cancelled'::text) >= 10 THEN 'high'::text
            WHEN count(*) FILTER (WHERE r.status = 'cancelled'::text) >= 5 THEN 'medium'::text
            ELSE 'low'::text
        END AS severity,
    jsonb_build_object('cancelled_count', count(*) FILTER (WHERE r.status = 'cancelled'::text), 'completed_count', count(*) FILTER (WHERE r.status = 'completed'::text), 'window_days', 30) AS metadata,
    now() AS computed_at
   FROM rides r
  WHERE r.created_at >= (now() - '30 days'::interval)
  GROUP BY r.user_id
 HAVING count(*) FILTER (WHERE r.status = 'cancelled'::text) >= 3 AND count(*) FILTER (WHERE r.status = 'completed'::text) = 0
UNION ALL
 SELECT 'driver'::text AS subject_type,
    r.driver_id::text AS subject_id,
    'low_rating'::text AS signal,
        CASE
            WHEN avg(r.rating) < 2::numeric THEN 'high'::text
            WHEN avg(r.rating) < 2.5 THEN 'medium'::text
            ELSE 'low'::text
        END AS severity,
    jsonb_build_object('avg_rating', round(avg(r.rating), 2), 'rated_rides', count(*)) AS metadata,
    now() AS computed_at
   FROM rides r
  WHERE r.driver_id IS NOT NULL AND r.rating IS NOT NULL AND r.created_at >= (now() - '60 days'::interval)
  GROUP BY r.driver_id
 HAVING avg(r.rating) < 3::numeric AND count(*) >= 5
UNION ALL
 SELECT 'ride'::text AS subject_type,
    r.id::text AS subject_id,
    'impossible_speed'::text AS signal,
    'high'::text AS severity,
    jsonb_build_object('speed_kmh', round(calc.speed_kmh::numeric, 1), 'distance_km', round(calc.distance_km::numeric, 2), 'duration_hours', round(calc.duration_hours, 3), 'pickup', r.pickup, 'dropoff', r.dropoff) AS metadata,
    now() AS computed_at
   FROM rides r
     JOIN LATERAL ( SELECT (6371 * 2)::double precision * asin(sqrt((sin(radians((r.dropoff_lat - r.pickup_lat) / 2::double precision)) ^ 2::double precision) + cos(radians(r.pickup_lat)) * cos(radians(r.dropoff_lat)) * (sin(radians((r.dropoff_lng - r.pickup_lng) / 2::double precision)) ^ 2::double precision))) AS distance_km,
            EXTRACT(epoch FROM r.payment_confirmed_at - r.created_at) / 3600.0 AS duration_hours) base ON true
     JOIN LATERAL ( SELECT base.distance_km,
            base.duration_hours,
                CASE
                    WHEN base.duration_hours > 0.0167 THEN base.distance_km / base.duration_hours::double precision
                    ELSE NULL::double precision
                END AS speed_kmh) calc ON true
  WHERE r.status = 'completed'::text AND r.pickup_lat IS NOT NULL AND r.pickup_lng IS NOT NULL AND r.dropoff_lat IS NOT NULL AND r.dropoff_lng IS NOT NULL AND r.payment_confirmed_at IS NOT NULL AND r.created_at >= (now() - '60 days'::interval) AND calc.speed_kmh IS NOT NULL AND calc.speed_kmh > 150::double precision WITH NO DATA;

create view public."wallet_balances" as  SELECT user_id,
    sum(amount) AS balance,
    count(*) AS movements_count,
    max(created_at) AS last_movement_at
   FROM wallet_movements
  GROUP BY user_id;

CREATE OR REPLACE FUNCTION public.admin_list_drivers(p_query text DEFAULT NULL::text, p_state text DEFAULT 'all'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS SETOF admin_driver_membership_status
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.higo_assert_admin('view_dashboard');
    return query
    select * from public.admin_driver_membership_status d
    where (coalesce(trim(p_query),'') = '' or
           d.full_name ilike '%' || trim(p_query) || '%' or
           d.phone ilike '%' || trim(p_query) || '%' or
           d.license_plate ilike '%' || trim(p_query) || '%' or
           d.payment_reference ilike '%' || trim(p_query) || '%')
      and (p_state = 'all' or d.membership_state = p_state)
    order by
        case d.membership_state when 'expired' then 1 when 'no_membership' then 2 when 'expiring_soon' then 3 else 4 end,
        d.expires_at nulls first,
        d.created_at desc
    limit greatest(1, least(coalesce(p_limit,50),200))
    offset greatest(coalesce(p_offset,0),0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_fraud_signals()
 RETURNS SETOF fraud_signals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NOT public.is_admin(auth.uid()) THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
        SELECT *
          FROM public.fraud_signals
         ORDER BY
            CASE severity WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
            computed_at DESC;
END;
$function$;

